('g5_1_sci_u4_L01_basic#1','sci',5,1,'u4','L01','g5_1_sci_u4_L01_basic','lesson_basic','SC5-1-u4-C2',1,'mc','auto','인체 골격 모형을 만들 때 뼈 도안을 무엇으로 연결하나요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C2","difficulty":1,"kind":"mc","stem":"인체 골격 모형을 만들 때 뼈 도안을 무엇으로 연결하나요?","options":[{"t":"똑딱단추","correct":true},{"t":"물풀","mis":"SC5-1-u4-X02"},{"t":"셀로판테이프","mis":"SC5-1-u4-X02"},{"t":"실과 바늘","mis":"SC5-1-u4-X02"}],"explanation":["준비물을 떠올려요.","눌러서 잇는 것이에요.","똑딱단추예요."]}'::jsonb),
