('g5_1_sci_u4_L01_challenge#1','sci',5,1,'u4','L01','g5_1_sci_u4_L01_challenge','lesson_challenge','SC5-1-u4-C2',2,'mc','auto','인체 골격 모형 활동의 차례로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X02']::text[],false,'{"seq":1,"concept":"SC5-1-u4-C2","difficulty":2,"kind":"mc","stem":"인체 골격 모형 활동의 차례로 알맞은 것은 어느 것인가요?","options":[{"t":"㉡ → ㉠ → ㉤ → ㉣ → ㉢","correct":true},{"t":"㉠ → ㉡ → ㉤ → ㉣ → ㉢","mis":"SC5-1-u4-X02"},{"t":"㉡ → ㉢ → ㉠ → ㉤ → ㉣","mis":"SC5-1-u4-X02"},{"t":"㉢ → ㉡ → ㉠ → ㉣ → ㉤","mis":"SC5-1-u4-X02"}],"explanation":["먼저 만들어요.","표현하고 따라 하고 함께 해요.","상상해 그리기는 맨 나중이에요."],"asset":{"type":"passage","lines":["㉠ 인체 골격 모형으로 다양한 몸동작을 표현한다.","㉡ 뼈 도안을 같은 기호끼리 맞대어 똑딱단추로 연결한다.","㉢ 몸속에 있는 여러 가지 기관을 상상해 모형에 그린다.","㉣ 친구와 함께 모형으로 다양한 상황을 표현한다.","㉤ 친구가 표현한 모형의 몸동작을 따라 한다."],"title":"인체 골격 모형 활동(차례가 섞여 있음)"}}'::jsonb),
