('g5_1_sci_u4_review_a#4','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C24',1,'mc','auto','노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X31']::text[],false,'{"seq":4,"concept":"SC5-1-u4-C24","difficulty":1,"kind":"mc","stem":"노폐물에 대한 설명으로 알맞은 것은 어느 것인가요?","options":[{"t":"몸에서 영양소가 쓰이면서 생긴, 몸에 필요 없는 것","correct":true},{"t":"몸에 꼭 필요한 영양소","mis":"SC5-1-u4-X31"},{"t":"먹은 음식물에서만 곧바로 생기는 것","mis":"SC5-1-u4-X31"},{"t":"숨을 쉴 때 들이마시는 산소","mis":"SC5-1-u4-X31"}],"explanation":["필요 없는 것이에요.","영양소가 쓰일 때 생겨요.","첫 번째예요."]}'::jsonb),
