('g5_1_sci_u4_review_a#18','sci',5,1,'u4','','g5_1_sci_u4_review_a','unit_review','SC5-1-u4-C32',3,'mc','auto','튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?',ARRAY['SC5-1-u4-X42','SC5-1-u4-X43']::text[],false,'{"seq":18,"concept":"SC5-1-u4-C32","difficulty":3,"kind":"mc","stem":"튼튼반 일지 ⑧에서 지우의 말을 바로잡은 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"「질병은 우리 몸의 기관과 관련이 있고, 생활 습관으로 예방에 도움을 줄 수 있어.」","correct":true},{"t":"「맞아, 운이 나빠서야.」","mis":"SC5-1-u4-X42"},{"t":"「예방은 어른만 할 수 있어.」","mis":"SC5-1-u4-X43"},{"t":"「질병은 약으로만 막을 수 있어.」","mis":"SC5-1-u4-X43"}],"explanation":["일지 ⑦을 떠올려요.","예방법이 있었어요.","첫 번째예요."],"asset":{"type":"passage","lines":["하람 — 「근육이 뼈를 밀어서 팔을 펴.」","도윤 — 「심장이 혈액을 만들어 내.」","서아 — 「배설은 똥을 누는 거야.」","민호 — 「운동할 때 심장이 빨리 뛰는 건 그냥 힘들어서야.」","지우 — 「질병은 운이 나빠서 걸리는 거야.」","다온 — 「손목에 차는 장치만 있으면 실천은 안 해도 돼.」"],"title":"튼튼반 탐구 일지 ⑧ 교실 토론"}}'::jsonb),
