('g5_1_sci_u4_review_d#23','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C36',4,'mc','auto','밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?',ARRAY['SC5-1-u4-X49','SC5-1-u4-X48']::text[],false,'{"seq":23,"concept":"SC5-1-u4-C36","difficulty":4,"kind":"mc","stem":"밤사이 착용형 장치가 심장박동 수가 갑자기 달라졌다며 경고 신호를 보냈어요. 가장 알맞은 행동은 어느 것인가요?","options":[{"t":"몸에 문제가 생겼을 수 있으니 어른께 알리고 몸 상태를 살핀다","correct":true},{"t":"신호를 무시하고 장치를 끈다","mis":"SC5-1-u4-X49"},{"t":"장치가 알아서 고쳐 줄 테니 그냥 둔다","mis":"SC5-1-u4-X48"},{"t":"장치를 더 예쁜 것으로 바꾼다","mis":"SC5-1-u4-X49"}],"explanation":["경고 신호의 뜻이에요.","문제가 생겼다는 신호예요.","첫 번째예요."]}'::jsonb),
('g5_1_sci_u4_review_d#24','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C22',4,'essay','teacher','튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SC5-1-u4-C22","difficulty":4,"kind":"essay","stem":"튼튼반 일지 ④의 ( ? )에 들어갈 길을 쓰고, 들이마실 때와 내쉴 때 폐가 하는 일을 각각 쓰세요.","answer_guide":{"answer":"예: ( ? )에는 「폐 → 숨관가지 → 숨관 → 코」가 들어간다. 숨을 들이마시면 폐는 우리 몸에 필요한 산소를 받아들이고, 숨을 내쉬면 몸속에서 생긴 이산화 탄소를 포함한 공기를 몸 밖으로 내보낸다. 두 길은 같은 길이고 방향만 반대이다.","scoring_points":["내쉬는 길을 바르게 썼는가","들이마실 때 산소를 받아들인다고 썼는가","내쉴 때 이산화 탄소를 내보낸다고 썼는가"]},"explanation":["거꾸로 써요.","들이마실 때 폐는요?","내쉴 때 폐는요?"],"asset":{"type":"passage","lines":["들이마실 때 — 코 → 숨관 → 숨관가지 → 폐","내쉴 때 — ( ? )","종이봉투 모형에 공기를 불어 넣자 봉투가 부풀었다.","한 친구가 어지러움을 느껴 잠시 활동을 멈추었다."],"title":"튼튼반 탐구 일지 ④ 호흡기관 모형"}}'::jsonb),
('g5_1_sci_u4_review_d#25','sci',5,1,'u4','','g5_1_sci_u4_review_d','unit_review','SC5-1-u4-C31',4,'essay','teacher','「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SC5-1-u4-C31","difficulty":4,"kind":"essay","stem":"「우리 몸의 구조와 기능」 단원에서 배운 것을 「뼈와 근육 → 소화·순환·호흡·배설기관 → 운동할 때 서로 영향을 주고받는 기관 → 질병과 건강한 생활」의 차례로 정리해 쓰세요.","answer_guide":{"answer":"예: 뼈는 몸의 형태를 만들고 지탱하며 몸속 기관을 보호하고, 근육이 줄어들거나 늘어나면서 뼈를 움직여 몸이 움직인다. 소화기관은 음식물을 잘게 쪼개 영양소를 흡수하고, 호흡기관은 산소를 받아들이며, 순환기관은 영양소와 산소를 온몸에 운반하고, 배설기관은 혈액 속의 노폐물을 걸러 몸 밖으로 내보낸다. 운동할 때 호흡이 빨라지고 심장이 빠르게 뛰는 것처럼 각 기관은 서로 영향을 주고받으며 작용한다. 다양한 질병은 우리 몸의 기관과 관련이 있으며, 건강한 생활 방식을 꾸준히 실천하면 예방에 도움이 된다.","scoring_points":["뼈와 근육이 하는 일을 썼는가","네 기관이 하는 일을 바르게 썼는가","서로 영향을 주고받음과 질병 예방을 썼는가"]},"explanation":["뼈와 근육부터예요.","네 기관을 넣어요.","서로 영향과 건강으로 마무리해요."]}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO5-1-u1-C1','soc',5,1,'u1',1,'지형의 뜻과 종류 — 다양하게 나타나는 땅의 생김새를 지형이라고 하며, 산봉우리가 길게 이어진 산지, 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기인 하천, 하천 주변에 주로 발달한 넓고 평평한 평야, 바다와 맞닿아 모래사장·갯벌이 나타나는 해안, 둘레가 바다로 둘러싸인 섬이 있음 · 우리나라는 국토의 약 70%가 산지이고 한 나라 안에 여러 지형이 어우러져 있음 · 이름을 외우기보다 특징을 견주어 이해함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],1),
('SO5-1-u1-C2','soc',5,1,'u1',2,'산지의 분포와 땅의 높낮이 — 지형도는 땅의 높낮이를 색으로 나타낸 지도이고 범례를 보면 색이 뜻하는 높이를 알 수 있음(색이 진할수록 높음) · 높고 험한 산지는 북쪽과 동쪽에, 낮고 완만한 산지는 남쪽과 서쪽에 많아 우리나라 땅은 북동쪽이 높고 남서쪽이 낮음 · 서쪽에서 동쪽으로 자른 단면도에서도 동쪽으로 갈수록 높아짐',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],2),
('SO5-1-u1-C3','soc',5,1,'u1',3,'하천의 흐름과 평야 — 물은 언제나 높은 곳에서 낮은 곳으로 흐르므로 큰 하천은 대부분 북쪽·동쪽의 높은 곳에서 시작해 남쪽·서쪽으로 흘러 바다로 감(북동쪽이 높고 남서쪽이 낮기 때문) · 하천 주변, 특히 큰 하천 하류 주변은 대부분 200 m 미만의 낮은 땅으로 넓고 평평한 평야가 발달해 논밭이 많음 · 하천은 오랜 시간 땅을 깎아 골짜기 같은 새 지형을 만들기도 함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],3),
('SO5-1-u1-C4','soc',5,1,'u1',4,'세 바다의 해안 — 우리나라는 동·서·남 삼면이 바다와 맞닿아 있고 바다와 육지가 만나는 선을 해안선이라고 함 · 동해안은 해안선이 단순하고 섬이 적으며 모래사장이 넓어 해수욕장이 발달 · 서해안과 남해안은 해안선이 복잡하고 섬이 많으며(남해안 다도해) 갯벌이 발달해 해산물을 얻고 간척하기도 함 · 파도가 암석을 깎아 해안 절벽과 동굴을 만들기도 함 — 해안 모습이 다르면 사람들의 생활도 다름',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],4),
('SO5-1-u1-C5','soc',5,1,'u1',5,'지형이 만든 경관과 보전 — 독특하고 아름다운 지형은 관광지가 됨(산지 — 바위 봉우리와 폭포의 산·고원 목장, 하천 — 두 물줄기가 합쳐지는 강가·지평선이 보이는 평야·깊은 계곡·하천이 깎은 한반도 모양 지형, 해안 — 갯벌·해수욕장·습지·해안 절벽) · 세계 지질 공원은 지질적 가치가 뛰어난 경관을 보전하고 교육·연구에 쓰려고 국제기구가 인증하는 곳(우리나라 처음은 제주) · 지질 공원 해설사는 지질·지형·자연·역사를 엮어 알기 쉽게 설명하고 훼손되지 않게 관리함 — 보고 배우되 그대로 둠',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],5),
('SO5-1-u1-C6','soc',5,1,'u1',5,'국토 여행 계획 세우기 — 주제 정하기(무엇을 보고 싶은지와 까닭) → 여행 정보 누리집 등으로 여행지 조사하기(디지털 영상 지도로 모습 확인) → 지도에 여행지를 표시하고 일정 순서대로 화살표로 이어 경로 나타내기(한 지역만 갈 때는 그 지역 백지도, 동선이 너무 길지 않게) → 공유 애플리케이션으로 나누고 예절 있게 댓글 쓰기',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],6),
('SO5-1-u1-C7','soc',5,1,'u1',7,'독도의 위치와 중요성 — 독도는 우리나라 영토의 동쪽 끝, 동해에 있는 섬으로 행정구역은 경상북도 울릉군이고 울릉도에서 87.4 km 떨어져 맑은 날 울릉도에서 보임(예로부터 우리 영토로 인식) · 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통·군사 면에서 중요하며, 연구 가치가 크고 주변 바다에 자원이 풍부함 · 공항이 없어 동해안 항구에서 배를 타고 울릉도를 거쳐 감',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],7),
('SO5-1-u1-C8','soc',5,1,'u1',8,'독도의 자연환경 — 동도와 서도 두 큰 섬과 여러 바위섬으로 이루어졌고 오래전 바닷속 화산 활동으로 만들어져 독특한 지형이 많음(바위 이름은 닮은 모습에서) · 대체로 온화하나 안개가 자주 끼고 흐린 날이 많으며 겨울에 눈이 많음 · 차가운 바닷물과 따뜻한 바닷물이 만나 좋은 어장을 이루고 해양 심층수(수심 200 m 아래, 영양분 많음)와 가스 하이드레이트(불타는 얼음)가 있어 경제적 가치가 큼 · 자연환경과 생태계를 보호하려고 독도 전체를 천연기념물로 지정',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],8),
('SO5-1-u1-C9','soc',5,1,'u1',9,'독도에 관한 옛 지도와 기록 — 우리나라 자료: 신라 장군 이사부가 우산국을 정벌한 일, 맑은 날 두 섬이 서로 보인다는 기록, 독도가 그려진 가장 오래된 지도 「팔도총도」, 독도를 울릉군이 다스린다고 정한 대한 제국 칙령(10월 25일 독도의 날) · 다른 나라 자료: 일본 국가 문서 「돗토리번 답변서」·「태정관 지령」(일본 땅이 아님), 일본이 만든 「삼국접양지도」(조선과 같은 색), 프랑스의 「조선왕국전도」, 연합국 최고 사령관 각서 부속 지도 · 옛 지도에는 그때 사람들의 영토 인식이 담겨 영토의 역사를 보여 주는 증거 — 누가 만들었고 무엇을 말하는지 읽기',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],9),
('SO5-1-u1-C10','soc',5,1,'u1',10,'독도를 지키기 위한 노력 — 안용복은 일본에 건너가 울릉도와 독도가 조선 땅임을 설명했고, 홍순칠과 울릉도 청년들은 독도 의용 수비대를 만들어 지키며 바위에 「한국령」을 새겼고, 최종덕은 주민 등록을 옮겨 최초의 독도 주민이 됨 · 정부는 선착장·주민 숙소·등대를 만들고 경찰인 독도 경비대를 파견(평소처럼 다스리는 우리 땅)하며 법과 정책으로 지키고 세계에 알림, 해양 경찰은 바다를 지킴 · 개인·학교·여러 단체도 방문·잘못된 정보 바로잡기·알리기 활동을 함 — 모두 함께',ARRAY['6사 국토 — 독도의 지리적 특징과 영토 수호 노력(초안)']::text[],10),
('SO5-1-u1-C11','soc',5,1,'u1',10,'우리 국토를 알리는 그림 만들기 — 그림으로 알리고 싶은 우리나라의 자연 경관(산지·해안·하천·독도 등)을 골라 생김새·동식물·사람·배경을 떠올려 조건을 구체적이고 자세하게 생각함(뜻이 흐린 조건은 무엇을 그릴지 정해 주지 못함) · 인공지능으로 만들고 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만듦 · 그림에 이름을 붙이고 어떤 조건으로 무엇을 표현했는지 스스로 소개함',ARRAY['6사 국토 — 우리나라 지형의 특징과 국토 여행(초안)']::text[],11)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO5-1-u1-X01','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'지형을 기후·인구·교통처럼 땅의 생김새가 아닌 것과 헷갈린다','지형 = 땅의 생김새'),
('SO5-1-u1-X02','soc',5,'u1',ARRAY['SO5-1-u1-C1']::text[],'산지·하천·평야·해안·섬의 뜻을 서로 바꾸어 짝짓는다','솟은 땅·흐르는 물·평평한 땅·바다와 만나는 곳·바다에 둘러싸인 땅'),
('SO5-1-u1-X03','soc',5,'u1',ARRAY['SO5-1-u1-C2','SO5-1-u1-C3']::text[],'우리나라 땅의 높낮이를 거꾸로(남서쪽이 높고 북동쪽이 낮다고, 또는 어디나 같다고) 안다','높은 산은 북쪽·동쪽에'),
('SO5-1-u1-X04','soc',5,'u1',ARRAY['SO5-1-u1-C2']::text[],'지형도·범례·단면도를 잘못 읽는다(색이 진하면 낮다고, 범례 대신 방위·축척을 본다 등)','범례의 색 = 높이 · 진할수록 높아요'),
('SO5-1-u1-X05','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'하천이 낮은 곳에서 높은 곳으로, 또는 아무 방향으로나 흐른다고 여겨 큰 하천이 남서쪽으로 흐르는 까닭을 놓친다','물은 높은 곳 → 낮은 곳'),
('SO5-1-u1-X06','soc',5,'u1',ARRAY['SO5-1-u1-C3']::text[],'평야가 높은 산지에 있다고 여기거나 하천과 상관없이 생긴다고 여긴다','하천 주변 · 200 m 미만'),
('SO5-1-u1-X07','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'동해안과 서해안·남해안의 특징(해안선·섬·모래사장·갯벌)을 바꾸어 안다','동해안 — 단순·모래사장 · 서·남해안 — 복잡·섬·갯벌'),
('SO5-1-u1-X08','soc',5,'u1',ARRAY['SO5-1-u1-C4']::text[],'갯벌·모래사장·해안 절벽 같은 해안 지형과 그곳의 생활(조개 캐기·해수욕·간척 등)을 맞지 않게 짝짓는다','진흙 땅·모래·파도가 깎은 바위'),
('SO5-1-u1-X09','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'경관이나 관광지를 그것을 만든 지형과 맞지 않게 짝짓는다','무엇이 이 경관을 만들었나?'),
('SO5-1-u1-X10','soc',5,'u1',ARRAY['SO5-1-u1-C5']::text[],'지질 공원·세계 지질 공원·해설사의 뜻을 오해하거나, 멋진 자연물을 기념으로 가져가도 된다고 여긴다','보전하고 알리는 곳 · 보고 배우되 그대로'),
('SO5-1-u1-X11','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'국토 여행 계획의 차례(주제 → 조사 → 경로 → 공유)나 알맞은 도구(누리집·디지털 영상 지도·백지도)를 헷갈린다','주제가 먼저'),
('SO5-1-u1-X12','soc',5,'u1',ARRAY['SO5-1-u1-C6']::text[],'온라인에서 계획서를 나눌 때 놀리거나 장난스러운 댓글도 괜찮다고 여긴다','화면 너머에도 친구가 있어요'),
('SO5-1-u1-X13','soc',5,'u1',ARRAY['SO5-1-u1-C1','SO5-1-u1-C2','SO5-1-u1-C3','SO5-1-u1-C9']::text[],'지형이나 옛 자료 공부를 이름·숫자·연도를 외우는 것으로 여겨 특징과 뜻을 읽어 내는 것을 놓친다','외우기보다 견주고 읽어 내기'),
('SO5-1-u1-X14','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도의 위치(동쪽 끝·동해)·행정구역·가는 길(공항 없음, 배로 울릉도를 거쳐)을 헷갈린다','동쪽 끝 · 경상북도 울릉군 · 배'),
('SO5-1-u1-X15','soc',5,'u1',ARRAY['SO5-1-u1-C7']::text[],'독도가 중요한 까닭(영토 경계·교통과 군사·연구 가치·자원)을 놓치거나 엉뚱한 까닭(등산·농사·관광객 수)을 댄다','경계 · 교통·군사 · 연구 · 자원'),
('SO5-1-u1-X16','soc',5,'u1',ARRAY['SO5-1-u1-C8']::text[],'독도의 자연환경(화산섬·동도와 서도·기후·어장·해양 심층수와 가스 하이드레이트·천연기념물 지정 까닭)을 잘못 안다','바닷속 화산 · 두 바닷물이 만나는 곳'),
('SO5-1-u1-X17','soc',5,'u1',ARRAY['SO5-1-u1-C9']::text[],'옛 지도와 기록이 무엇을 말하는지 놓친다(다른 나라가 만든 자료의 뜻, 누가 만든 자료인지, 영토 인식의 증거라는 점)','누가 만들었고 무엇을 말하나?'),
('SO5-1-u1-X18','soc',5,'u1',ARRAY['SO5-1-u1-C10']::text[],'독도를 지킨 사람과 한 일을 바꾸어 짝짓거나, 독도를 지키는 일을 정부·경비대만의 일로 여긴다','안용복·홍순칠·최종덕 · 그리고 우리'),
('SO5-1-u1-X19','soc',5,'u1',ARRAY['SO5-1-u1-C11']::text[],'그림을 만드는 조건을 흐리게 쓰거나, 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 된다고 여긴다','조건은 자세히 · 소개는 내가')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_soc_u1_L01_basic#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?',ARRAY['SO5-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"다양하게 나타나는 땅의 생김새를 무엇이라고 하나요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"교통","mis":"SO5-1-u1-X01"}],"explanation":["땅의 모습을 가리키는 말이에요.","산지·하천·평야·해안·섬이 모두 지형이에요.","기후는 날씨, 인구는 사람 수예요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'mc','auto','산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"산봉우리가 길게 이어져 솟아 있는 지형은 어느 것인가요?","options":[{"t":"산지","correct":true},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"}],"explanation":["산이 여럿 이어진 땅이에요.","이런 땅을 산지라고 해요.","우리 국토의 약 70%가 산지예요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#3','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'sa','auto','둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"sa","stem":"둘레가 바다로 둘러싸인 땅을 무엇이라고 하나요? 한 글자로 쓰세요.","answer":["섬"],"explanation":["사방이 바다예요.","배를 타야 갈 수 있어요.","이런 땅이 섬이에요."],"mis":"SO5-1-u1-X02"}'::jsonb),
('g5_1_soc_u1_L01_basic#4','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',1,'ox','auto','하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"하천은 낮은 곳에서 높은 곳으로 흐르는 물줄기예요.","answer":"X","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물줄기는 흐르는 방향이 정해져 있지 않기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["하천은 크고 작은 물줄기예요.","물은 높은 곳에서 낮은 곳으로 흘러요.","그래서 하천도 그렇게 흘러요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#5','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'match','auto','다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"다섯 장의 땅 카드를 보고 카드와 지형 이름을 알맞게 이으세요.","pairs":[{"l":"㉮","r":"섬"},{"l":"㉯","r":"산지"},{"l":"㉰","r":"하천"},{"l":"㉱","r":"평야"}],"mis":"SO5-1-u1-X02","explanation":["㉮는 바다에 둘러싸여 있어요.","㉯는 솟아 있고, ㉰는 흘러요.","㉱는 넓고 평평해요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb),
('g5_1_soc_u1_L01_basic#6','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"다섯 장의 땅 카드에서 ㉲에 알맞은 지형은 어느 것인가요?","options":[{"t":"해안","correct":true},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"평야","mis":"SO5-1-u1-X02"},{"t":"하천","mis":"SO5-1-u1-X02"}],"explanation":["㉲는 바다와 맞닿아 있어요.","모래사장이나 갯벌이 보여요.","이곳이 해안이에요."],"asset":{"type":"passage","lines":["㉮ 둘레가 모두 바다로 둘러싸인 땅","㉯ 산봉우리가 길게 이어져 솟아 있는 땅","㉰ 높은 곳에서 낮은 곳으로 흐르는 크고 작은 물줄기","㉱ 물줄기 주변에 넓고 평평하게 펼쳐진 땅","㉲ 바다와 맞닿아 모래사장이나 갯벌이 보이는 곳"],"title":"다섯 장의 땅 카드"}}'::jsonb),
('g5_1_soc_u1_L01_basic#7','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"넓고 평평하게 펼쳐져 있으며 하천 주변에 주로 발달하는 지형은 어느 것인가요?","options":[{"t":"평야","correct":true},{"t":"산지","mis":"SO5-1-u1-X02"},{"t":"섬","mis":"SO5-1-u1-X02"},{"t":"해안","mis":"SO5-1-u1-X02"}],"explanation":["넓고 평평한 땅이에요.","물줄기 곁에 잘 생겨요.","이런 땅이 평야예요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#8','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'mc','auto','지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"mc","stem":"지난여름 가족과 해수욕장에서 모래 놀이를 했다면 그곳은 어떤 지형일까요?","options":[{"t":"해안","correct":true},{"t":"산지","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X08"},{"t":"하천","mis":"SO5-1-u1-X08"}],"explanation":["해수욕장 곁에는 바다가 있어요.","모래사장은 바다와 맞닿은 곳에 생겨요.","그래서 해안이에요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#9','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',2,'ox','auto','우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"ox","stem":"우리나라에는 산지·하천·평야·해안·섬이 모두 나타나요.","answer":"O","reason_options":[{"t":"한 나라 안에 여러 땅의 생김새가 어우러져 있기 때문에","correct":true},{"t":"우리나라에는 산지만 있기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["우리 국토에는 여러 지형이 있어요.","높은 산부터 바닷가까지 있어요.","그래서 지형이 다양해요."]}'::jsonb),
('g5_1_soc_u1_L01_basic#10','soc',5,1,'u1','L01','g5_1_soc_u1_L01_basic','lesson_basic','SO5-1-u1-C1',3,'mc','auto','지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C1","difficulty":3,"kind":"mc","stem":"지형을 공부하는 바른 태도가 아닌 것은 어느 것인가요?","options":[{"t":"산맥과 하천 이름을 빠짐없이 외우는 데에만 힘쓴다","correct":true},{"t":"여러 지형의 특징을 견주어 살펴본다","mis":"SO5-1-u1-X13"},{"t":"지도나 영상 자료로 지형의 모습을 확인한다","mis":"SO5-1-u1-X13"},{"t":"우리 국토의 아름다움을 느끼며 살펴본다","mis":"SO5-1-u1-X13"}],"explanation":["외우는 것이 목표가 아니에요.","특징을 견주고 자료로 확인해요.","국토의 아름다움도 느껴요."]}'::jsonb),
('g5_1_soc_u1_L01_challenge#1','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'sa','auto','산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"sa","stem":"산지·하천·평야·해안·섬처럼 다양하게 나타나는 땅의 생김새를 두 글자로 무엇이라고 하나요?","answer":["지형"],"explanation":["땅 지(地) 자가 들어가요.","땅의 모양을 뜻해요.","지형이에요."],"mis":"SO5-1-u1-X01"}'::jsonb),
('g5_1_soc_u1_L01_challenge#2','soc',5,1,'u1','L01','g5_1_soc_u1_L01_challenge','lesson_challenge','SO5-1-u1-C1',2,'match','auto','지형과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C1","difficulty":2,"kind":"match","stem":"지형과 그 특징을 알맞게 이으세요.","pairs":[{"l":"산지","r":"산봉우리가 길게 이어진 땅"},{"l":"하천","r":"높은 곳에서 낮은 곳으로 흐르는 물줄기"},{"l":"해안","r":"바다와 맞닿은 곳"},{"l":"섬","r":"둘레가 바다로 둘러싸인 땅"}],"mis":"SO5-1-u1-X02","explanation":["솟은 땅은 산지예요.","흐르는 물줄기는 하천이에요.","바다와 만나면 해안, 둘러싸이면 섬이에요."]}'::jsonb),
