('g5_1_soc_u1_L05_basic#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C3',2,'ox','auto','우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"ox","stem":"우리나라는 동쪽이 높고 서쪽이 낮아서 큰 하천이 대부분 남쪽과 서쪽으로 흘러가요.","answer":"O","reason_options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"하천은 땅의 높낮이와 상관없이 흐르기 때문에","mis":"SO5-1-u1-X05"}],"mis":"SO5-1-u1-X05","explanation":["땅의 높낮이가 하천을 정해요.","물은 낮은 곳으로 흘러요.","그래서 남쪽과 서쪽으로 흘러요."]}'::jsonb),
('g5_1_soc_u1_L05_basic#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C5',2,'mc','auto','지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X01']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"지질 공원 해설사가 하는 일로 알맞은 것은 어느 것인가요?","options":[{"t":"지질 공원을 안내하고 훼손되지 않도록 관리한다","correct":true},{"t":"공원에 들어오는 사람을 모두 막는다","mis":"SO5-1-u1-X10"},{"t":"공원의 멋진 바위를 캐서 판다","mis":"SO5-1-u1-X10"},{"t":"날마다 날씨를 예보한다","mis":"SO5-1-u1-X01"}],"explanation":["해설사는 공원을 알려요.","알기 쉽게 설명해요.","공원이 망가지지 않게 지켜요."]}'::jsonb),
('g5_1_soc_u1_L05_basic#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_basic','lesson_basic','SO5-1-u1-C6',3,'mc','auto','친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 여행 계획서에 댓글을 쓸 때의 태도로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"재미있으라고 친구를 놀리는 말을 남긴다","correct":true},{"t":"보고 느낀 점을 예의 있게 쓴다","mis":"SO5-1-u1-X12"},{"t":"좋아 보이는 점을 찾아 칭찬한다","mis":"SO5-1-u1-X12"},{"t":"궁금한 점을 정중하게 묻는다","mis":"SO5-1-u1-X12"}],"explanation":["온라인에서도 예절을 지켜요.","놀리는 댓글은 상처를 줘요.","느낀 점과 칭찬을 써요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#1','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'mc','auto','「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"「동해안·서해안·남해안의 모습을 견주어 보고 싶어」라는 생각에서 나올 여행 주제로 알맞은 것은 어느 것인가요?","options":[{"t":"세 바다의 해안 지형을 찾아가는 여행","correct":true},{"t":"높은 산지만 골라 오르는 여행","mis":"SO5-1-u1-X11"},{"t":"하천을 따라 상류에서 하류까지 내려가는 여행","mis":"SO5-1-u1-X11"},{"t":"넓은 평야에서 농사 체험을 하는 여행","mis":"SO5-1-u1-X11"}],"explanation":["주제는 보고 싶은 것에서 나와요.","세 바다를 견주고 싶어 해요.","해안 지형 여행이 알맞아요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#2','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',2,'sa','auto','여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서에서 여행지를 지도에 표시한 뒤 일정 순서대로 무엇으로 이어 여행 경로를 나타내나요? 세 글자로 쓰세요.","answer":["화살표"],"explanation":["순서를 보여 줘요.","한쪽 끝이 뾰족해요.","화살표로 이어요."],"mis":"SO5-1-u1-X11"}'::jsonb),
('g5_1_soc_u1_L05_challenge#3','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X13','SO5-1-u1-X11']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"여행 경로의 순서를 정할 때 가장 알맞게 생각한 것은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행의 목적에 맞추어 순서를 정한다","correct":true},{"t":"이름이 가장 긴 곳부터 간다","mis":"SO5-1-u1-X13"},{"t":"가장 먼 곳끼리 번갈아 간다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 먼저 넣는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길면 힘들어요.","목적에 맞게 순서를 정해요.","화살표로 이어요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#4','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',3,'mc','auto','완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X11','SO5-1-u1-X12']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"완성한 여행 계획서를 공유 애플리케이션으로 나누면 좋은 점으로 알맞은 것은 어느 것인가요?","options":[{"t":"자리에 앉아서도 친구들의 계획서를 언제든 볼 수 있다","correct":true},{"t":"여행에 드는 돈이 줄어든다","mis":"SO5-1-u1-X11"},{"t":"계획서를 고칠 수 없게 잠긴다","mis":"SO5-1-u1-X11"},{"t":"댓글은 아무렇게나 써도 된다","mis":"SO5-1-u1-X12"}],"explanation":["사진으로 찍어 올려요.","앞에 나오지 않아도 돼요.","언제든 서로의 계획을 봐요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#5','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'ox','auto','지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"ox","stem":"지질 공원의 멋진 바위 조각은 기념으로 조금 떼어 와 간직해도 괜찮아요.","answer":"X","reason_options":[{"t":"오랜 시간이 만든 단 하나뿐인 자연이라 떼어 오면 되돌릴 수 없기 때문에","correct":true},{"t":"바위는 다시 금방 자라나기 때문에","mis":"SO5-1-u1-X10"}],"mis":"SO5-1-u1-X10","explanation":["바위와 지형은 오랜 시간이 만들었어요.","떼어 오면 되돌릴 수 없어요.","눈으로 보고 마음에 담아요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#6','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'error','auto','지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"error","stem":"지질 공원 해설사의 말을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"라온 — 「해설사는 지형만 설명하고 마을의 옛이야기는 다루지 않아.」","correct":true,"mis_target":"SO5-1-u1-X10"},{"t":"예준 — 「바위 줄무늬가 생긴 까닭을 알기 쉽게 설명했어.」","mis":"SO5-1-u1-X10"},{"t":"다인 — 「공원이 훼손되지 않게 지키는 일도 해.」","mis":"SO5-1-u1-X10"}],"explanation":["해설사는 지질·지형·자연·역사를 엮어요.","소금 이야기는 역사예요.","그래서 라온이의 말이 틀렸어요."],"asset":{"type":"speech","turns":[{"who":"해설사","text":"이 바위 줄무늬는 아주 오랜 시간 동안 흙과 모래가 쌓여서 생겼어요."},{"who":"해설사","text":"옛날 이 마을 사람들은 이 바위 아래에서 소금을 말렸다고 해요."},{"who":"해설사","text":"바위를 만지거나 떼어 가면 다시 되돌릴 수 없으니 눈으로만 보아 주세요."}]}}'::jsonb),
('g5_1_soc_u1_L05_challenge#7','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C5',3,'mc','auto','지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"지질 공원 해설사가 되려는 사람에게 필요한 것으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"공원 바위를 마음대로 가져갈 수 있는 힘","correct":true},{"t":"자연환경에 대한 꾸준한 관심","mis":"SO5-1-u1-X10"},{"t":"지질과 지형에 관한 정확한 지식","mis":"SO5-1-u1-X13"},{"t":"자연을 아끼고 사랑하는 마음","mis":"SO5-1-u1-X10"}],"explanation":["관심과 사랑하는 마음이 필요해요.","정확한 지식도 필요해요.","자연물을 가져가면 안 돼요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#8','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C2',4,'mc','auto','주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X02','SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C2","difficulty":4,"kind":"mc","stem":"주제 ①에서 배운 내용을 하나로 잇는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"땅의 높낮이 하나가 산지의 분포, 하천의 방향, 평야의 자리까지 정해 준다","correct":true},{"t":"산지·하천·평야는 서로 아무 관계가 없다","mis":"SO5-1-u1-X02"},{"t":"하천은 높낮이와 상관없이 동쪽으로 흐른다","mis":"SO5-1-u1-X05"},{"t":"평야는 높은 산지 위에 주로 펼쳐진다","mis":"SO5-1-u1-X06"}],"explanation":["높은 산은 북·동쪽이에요.","하천은 남·서쪽으로 흘러요.","하천 주변에 평야가 펼쳐져요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#9','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'mc','auto','「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09','SO5-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"mc","stem":"「갯벌과 습지의 생물을 만나는 여행」을 주제로 정했어요. 이 주제에 가장 잘 어울리는 여행지 묶음은 어느 것인가요?","options":[{"t":"서해안의 갯벌 체험장과 남해안의 갯벌·갈대밭 습지","correct":true},{"t":"높은 산지의 목장과 바위 봉우리 산","mis":"SO5-1-u1-X09"},{"t":"동해안의 모래 해수욕장과 서핑 바닷가","mis":"SO5-1-u1-X08"},{"t":"지평선이 보이는 평야와 두 물줄기가 합쳐지는 강가","mis":"SO5-1-u1-X09"}],"explanation":["주제에 맞는 곳을 골라요.","갯벌은 서·남해안에 발달했어요.","습지에 갈대밭도 있어요."]}'::jsonb),
('g5_1_soc_u1_L05_challenge#10','soc',5,1,'u1','L05','g5_1_soc_u1_L05_challenge','lesson_challenge','SO5-1-u1-C6',4,'essay','teacher','자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"자신만의 국토 여행 주제를 하나 정해 그 까닭을 쓰고, 여행지 두 곳을 어떤 지형인지와 함께 쓴 뒤, 계획을 친구들과 나눌 때 지킬 점을 쓰세요.","answer_guide":{"answer":"예: 나의 여행 주제는 「하천을 따라 내려가는 여행」이다. 물이 어디서 시작해 어디로 흘러가는지 직접 보고 싶기 때문이다. 먼저 깊은 골짜기에 물과 폭포가 어우러진 계곡(하천)에 가고, 그다음 하천 주변에 펼쳐진 넓은 평야에 가겠다. 친구들과 나눌 때는 장난스러운 댓글 대신 느낀 점과 좋은 점을 예의 있게 쓰겠다.","scoring_points":["주제와 까닭을 썼는가","여행지 두 곳과 그 지형을 맞게 썼는가","온라인 예절을 썼는가"]},"explanation":["주제가 먼저예요.","여행지의 지형을 함께 써요.","나눌 때는 예절을 지켜요."]}'::jsonb),
('g5_1_soc_u1_L07_basic#1','soc',5,1,'u1','L07','g5_1_soc_u1_L07_basic','lesson_basic','SO5-1-u1-C7',1,'mc','auto','독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C7","difficulty":1,"kind":"mc","stem":"독도는 우리나라 영토의 어느 쪽 끝에 있는 섬인가요?","options":[{"t":"동쪽 끝","correct":true},{"t":"서쪽 끝","mis":"SO5-1-u1-X14"},{"t":"남쪽 끝","mis":"SO5-1-u1-X14"},{"t":"북쪽 끝","mis":"SO5-1-u1-X14"}],"explanation":["독도는 동해에 있어요.","우리 영토의 동쪽 끝이에요.","동쪽 경계를 알려 줘요."]}'::jsonb),
