('g5_1_soc_u1_L10_basic#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',1,'sa','auto','정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":1,"kind":"sa","stem":"정부가 독도에 파견해 주민과 관광객의 편의와 안전을 지키게 한 경찰을 무엇이라고 하나요? (□□ □□□)","answer":["독도 경비대","독도경비대"],"explanation":["독도에 머무는 경찰이에요.","안전을 지키고 해안을 경계해요.","독도 경비대예요."],"mis":"SO5-1-u1-X18"}'::jsonb),
('g5_1_soc_u1_L10_basic#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',1,'ox','auto','인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C11","difficulty":1,"kind":"ox","stem":"인공지능으로 그림을 만들 때는 조건을 구체적이고 자세하게 나타낼수록 원하는 그림에 가까워져요.","answer":"O","reason_options":[{"t":"조건이 자세해야 무엇을 어떻게 그릴지 또렷해지기 때문에","correct":true},{"t":"인공지능은 조건이 짧을수록 더 잘 알아듣기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["흐린 조건은 그림을 정해 주지 못해요.","모습과 행동까지 적어요.","자세할수록 좋아요."]}'::jsonb),
('g5_1_soc_u1_L10_basic#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X13']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 「한국령」을 새긴 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"독도가 우리 영토임을 알리고 지키려는 의지를 나타내려고","correct":true},{"t":"바위의 이름을 붙여 관광객을 모으려고","mis":"SO5-1-u1-X18"},{"t":"배가 길을 잃지 않도록 방향을 알려 주려고","mis":"SO5-1-u1-X18"},{"t":"바위의 높이를 재어 기록해 두려고","mis":"SO5-1-u1-X13"}],"explanation":["「한국령」은 한국의 영토라는 뜻이에요.","우리 땅임을 알렸어요.","지키겠다는 의지예요."]}'::jsonb),
('g5_1_soc_u1_L10_basic#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'match','auto','독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"match","stem":"독도를 지킨 사람들 카드를 보고 카드와 알맞은 이름을 이으세요.","pairs":[{"l":"㉠","r":"안용복"},{"l":"㉡","r":"홍순칠"},{"l":"㉢","r":"최종덕"},{"l":"㉣","r":"독도 경비대"}],"mis":"SO5-1-u1-X18","explanation":["㉠은 조선 시대 일본에 건너갔어요.","㉡은 의용 수비대, ㉢은 첫 주민이에요.","㉣은 지금 독도를 지키는 경찰이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb),
('g5_1_soc_u1_L10_basic#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'mc','auto','오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"오늘날 정부가 독도를 지키려고 하는 일로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"독도에 큰 공항을 지어 관광객만 받는다","correct":true},{"t":"선착장·주민 숙소·등대를 만든다","mis":"SO5-1-u1-X18"},{"t":"독도와 주변 바다를 지키는 법과 정책을 만든다","mis":"SO5-1-u1-X18"},{"t":"세계 여러 나라에 독도가 우리 고유의 영토임을 알린다","mis":"SO5-1-u1-X18"}],"explanation":["정부는 시설을 만들고 경비대를 보내요.","법과 정책으로 지켜요.","세계에 알려요."]}'::jsonb),
('g5_1_soc_u1_L10_basic#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',2,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X19']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C11","difficulty":2,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모에서 독도와 어울리지 않는 조건은 어느 것인가요?","options":[{"t":"조건 ㉱","correct":true},{"t":"조건 ㉯","mis":"SO5-1-u1-X16"},{"t":"조건 ㉰","mis":"SO5-1-u1-X16"},{"t":"조건 ㉮","mis":"SO5-1-u1-X19"}],"explanation":["독도에는 목장이 없어요.","괭이갈매기·해국·사철나무는 독도의 모습이에요.","㉱는 독도와 맞지 않아요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb),
('g5_1_soc_u1_L10_basic#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C10',2,'ox','auto','독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"ox","stem":"독도를 지키는 일은 정부와 경비대가 하니 나는 관심을 갖지 않아도 돼요.","answer":"X","reason_options":[{"t":"개인·학교·여러 단체가 함께 관심을 기울이고 노력해야 더 잘 지킬 수 있기 때문에","correct":true},{"t":"독도는 아무도 지킬 필요가 없는 섬이기 때문에","mis":"SO5-1-u1-X18"}],"mis":"SO5-1-u1-X18","explanation":["독도 지키기는 모두의 일이에요.","관심을 갖고 바르게 알아요.","알리는 활동에 참여해요."]}'::jsonb),
('g5_1_soc_u1_L10_basic#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_basic','lesson_basic','SO5-1-u1-C11',3,'mc','auto','그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"그림 조건 메모의 조건 ㉮ 「예쁜 풍경」만으로는 원하는 그림을 얻기 어려운 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람마다 떠올리는 모습이 달라 무엇을 그릴지 정해 주지 못하기 때문에","correct":true},{"t":"글자 수가 너무 많기 때문에","mis":"SO5-1-u1-X19"},{"t":"인공지능이 우리말을 읽지 못하기 때문에","mis":"SO5-1-u1-X19"},{"t":"예쁜 것은 그릴 수 없기 때문에","mis":"SO5-1-u1-X19"}],"explanation":["「예쁜 풍경」은 뜻이 흐려요.","무엇을 그릴지 정해지지 않아요.","자세한 조건이 필요해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb),
('g5_1_soc_u1_L10_challenge#1','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'mc','auto','바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?',ARRAY['SO5-1-u1-X10','SO5-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"바다에서 국민의 생명과 재산을 지키고 해상 교통 질서와 바다 환경을 지키는 직업은 어느 것인가요?","options":[{"t":"해양 경찰","correct":true},{"t":"지질 공원 해설사","mis":"SO5-1-u1-X10"},{"t":"등대지기","mis":"SO5-1-u1-X18"},{"t":"선장","mis":"SO5-1-u1-X18"}],"explanation":["바다를 지키는 경찰이에요.","사고가 나면 사람을 구해요.","바다 오염도 막아요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#2','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',2,'sa','auto','홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"sa","stem":"홍순칠과 독도 의용 수비대가 독도 바위에 새긴 세 글자는 무엇인가요?","answer":["한국령"],"explanation":["「한국의 영토」라는 뜻이에요.","바위에 새겼어요.","한국령이에요."],"mis":"SO5-1-u1-X18"}'::jsonb),
('g5_1_soc_u1_L10_challenge#3','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X15','SO5-1-u1-X14']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"독도에 군인이 아니라 경찰인 독도 경비대가 머무는 것이 뜻하는 바로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"우리나라가 독도를 우리 영토로서 평소처럼 다스리고 있다는 뜻","correct":true},{"t":"독도가 아직 어느 나라 땅인지 정해지지 않았다는 뜻","mis":"SO5-1-u1-X18"},{"t":"독도에는 사람이 살 수 없다는 뜻","mis":"SO5-1-u1-X15"},{"t":"독도에 관광객이 오지 못한다는 뜻","mis":"SO5-1-u1-X14"}],"explanation":["경찰은 나라 안의 질서를 지켜요.","독도도 우리 땅 안이에요.","평소처럼 다스린다는 뜻이에요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#4','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'mc','auto','사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X18','SO5-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"사이버 외교 사절단이 독도에 관한 잘못된 정보를 찾아 고치도록 하는 활동이 필요한 까닭은 무엇인가요?","options":[{"t":"세계 사람들이 독도를 우리 땅으로 바르게 알도록 하려고","correct":true},{"t":"독도를 찾는 관광객 수를 늘리려고","mis":"SO5-1-u1-X15"},{"t":"독도에 새로운 시설을 지으려고","mis":"SO5-1-u1-X18"},{"t":"독도의 옛 이름을 새로 정하려고","mis":"SO5-1-u1-X17"}],"explanation":["잘못된 정보는 오해를 낳아요.","틀린 내용을 바로잡아요.","세계가 바르게 알게 돼요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#5','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'ox','auto','인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능이 만든 그림을 소개할 때는 인공지능이 만들었으니 무엇을 표현했는지 설명하지 않아도 돼요.","answer":"X","reason_options":[{"t":"조건을 생각하고 고른 사람은 나이므로 어떤 조건으로 무엇을 표현했는지 스스로 설명해야 하기 때문에","correct":true},{"t":"인공지능 그림은 이름을 붙일 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["조건을 고른 사람은 나예요.","그림 이름을 말해요.","어떤 조건으로 무엇을 표현했는지 설명해요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#6','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',3,'error','auto','독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":6,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"error","stem":"독도를 지킨 사람들 카드를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「㉢은 조선 시대에 일본에 건너간 안용복이야.」","correct":true,"mis_target":"SO5-1-u1-X18"},{"t":"보민 — 「㉣은 지금도 독도에 머무는 경찰이야.」","mis":"SO5-1-u1-X18"},{"t":"지유 — 「㉡은 울릉도 청년들과 함께 독도를 지켰어.」","mis":"SO5-1-u1-X18"}],"explanation":["㉢은 첫 독도 주민이에요.","첫 독도 주민은 최종덕이에요.","안용복은 ㉠이에요."],"asset":{"type":"passage","lines":["㉠ 조선 시대에 두 차례 일본으로 건너가 두 섬이 조선 땅이라고 설명했다.","㉡ 울릉도 청년들과 의용 수비대를 만들어 독도를 지켰다.","㉢ 울릉도의 어부로, 독도로 주민 등록을 옮겨 첫 독도 주민이 되었다.","㉣ 독도에 머물며 주민과 관광객의 안전을 지키고 해안을 경계한다."],"title":"독도를 지킨 사람들 카드"}}'::jsonb),
('g5_1_soc_u1_L10_challenge#7','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',3,'mc','auto','표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"표현하고 싶은 경관이 제대로 그려지지 않았을 때 할 일로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조건을 더하거나 다르게 입력해 마음에 들 때까지 다시 만든다","correct":true},{"t":"그리기를 그만둔다","mis":"SO5-1-u1-X19"},{"t":"아무 그림이나 골라서 쓴다","mis":"SO5-1-u1-X19"},{"t":"조건을 모두 지우고 그냥 둔다","mis":"SO5-1-u1-X19"}],"explanation":["한 번에 안 되어도 괜찮아요.","조건을 고쳐 보아요.","여러 번 다시 만들어요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#8','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'mc','auto','초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"초등학생들이 독도에 찾아가 경비대를 만나고, 명예시민 등록과 각국 대사관에 편지 쓰기를 하기로 했어요. 이 활동의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"개인과 학교도 독도에 관심을 불러일으키고 세계에 독도가 우리 땅임을 알리는 데 함께한다","correct":true},{"t":"독도를 지키는 일은 학생과 관계없다","mis":"SO5-1-u1-X18"},{"t":"독도에 학교를 새로 지으려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도에 사는 동물 수를 세려는 것이다","mis":"SO5-1-u1-X16"}],"explanation":["방문하고 알리는 활동이에요.","세계에 바른 역사를 알려요.","학생도 함께 지켜요."]}'::jsonb),
('g5_1_soc_u1_L10_challenge#9','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C11',4,'mc','auto','「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"mc","stem":"「우리나라의 아름다운 섬, 독도」 그림을 소개하는 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「그림 이름은 「아침의 독도」입니다. 동도와 서도, 하늘을 나는 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 자연을 표현했습니다.」","correct":true},{"t":"「인공지능이 만들었으니 제 생각은 없어요.」","mis":"SO5-1-u1-X19"},{"t":"「이름은 없지만 예쁘니까 봐 주세요.」","mis":"SO5-1-u1-X19"},{"t":"「산 위 목장의 소를 넣어 독도를 표현했습니다.」","mis":"SO5-1-u1-X16"}],"explanation":["그림 이름을 말해요.","어떤 조건을 썼는지 말해요.","무엇을 표현했는지 설명해요."],"asset":{"type":"passage","lines":["조건 ㉮ — 예쁜 풍경","조건 ㉯ — 독도 동도와 서도, 하늘을 나는 괭이갈매기","조건 ㉰ — 바위에 핀 해국과 사철나무, 맑은 아침 바다","조건 ㉱ — 산 위 목장에서 풀을 뜯는 소"],"title":"「우리나라의 아름다운 섬, 독도」 그림 조건 메모"}}'::jsonb),
('g5_1_soc_u1_L10_challenge#10','soc',5,1,'u1','L10','g5_1_soc_u1_L10_challenge','lesson_challenge','SO5-1-u1-C10',4,'essay','teacher','독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"essay","stem":"독도를 지키려고 노력한 사람이나 집단 두 곳을 골라 한 일을 쓰고, 내가 독도를 알리려고 할 수 있는 일을 하나 쓰세요.","answer_guide":{"answer":"예: 안용복은 조선 시대에 두 차례 일본으로 건너가 울릉도와 독도가 조선의 땅이라고 설명했다. 정부는 독도 경비대를 파견하고 선착장과 등대를 만들어 독도를 지킨다. 나는 독도의 위치와 자연환경, 옛 지도에 나타난 독도를 소개하는 그림을 만들어 친구들과 가족에게 알리겠다.","scoring_points":["노력한 사람이나 집단을 둘 골랐는가","각각 한 일을 바르게 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["옛날과 오늘의 노력을 골라요.","한 일을 바르게 짝지어요.","나도 함께할 수 있어요."]}'::jsonb),
('g5_1_soc_u1_review_a#1','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',1,'mc','auto','새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?',ARRAY['SO5-1-u1-X01','SO5-1-u1-X14']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"mc","stem":"새봄이네가 여행하며 만난 산지·하천·평야·해안·섬을 함께 이르는 말은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기후","mis":"SO5-1-u1-X01"},{"t":"인구","mis":"SO5-1-u1-X01"},{"t":"항로","mis":"SO5-1-u1-X14"}],"explanation":["모두 땅의 생김새예요.","땅의 생김새를 지형이라고 해요.","기후는 날씨예요."]}'::jsonb),
('g5_1_soc_u1_review_a#2','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',1,'mc','auto','새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?',ARRAY['SO5-1-u1-X04']::text[],false,'{"seq":2,"concept":"SO5-1-u1-C2","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 지형도에서 진한 갈색인 것은 무엇을 뜻하나요?","options":[{"t":"땅이 아주 높다","correct":true},{"t":"땅이 아주 낮다","mis":"SO5-1-u1-X04"},{"t":"바다가 깊다","mis":"SO5-1-u1-X04"},{"t":"사람이 많이 산다","mis":"SO5-1-u1-X04"}],"explanation":["범례를 보면 알 수 있어요.","진한 갈색은 높은 땅이에요.","높은 산지예요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb),
('g5_1_soc_u1_review_a#3','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',1,'mc','auto','새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?',ARRAY['SO5-1-u1-X05']::text[],false,'{"seq":3,"concept":"SO5-1-u1-C3","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ②에서 물줄기가 서쪽의 낮은 곳으로 흘러간 까닭은 무엇인가요?","options":[{"t":"물은 높은 곳에서 낮은 곳으로 흐르기 때문에","correct":true},{"t":"물은 낮은 곳에서 높은 곳으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"물은 언제나 동쪽으로 흐르기 때문에","mis":"SO5-1-u1-X05"},{"t":"바람이 물을 밀었기 때문에","mis":"SO5-1-u1-X05"}],"explanation":["물은 아래로 흘러요.","서쪽이 더 낮아요.","그래서 서쪽으로 흘렀어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb),
('g5_1_soc_u1_review_a#4','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',1,'mc','auto','새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO5-1-u1-C4","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ③처럼 바닷물이 빠지면 드러나는 넓은 진흙 땅을 무엇이라고 하나요?","options":[{"t":"갯벌","correct":true},{"t":"모래사장","mis":"SO5-1-u1-X08"},{"t":"해안 절벽","mis":"SO5-1-u1-X08"},{"t":"평야","mis":"SO5-1-u1-X06"}],"explanation":["바닷물이 드나드는 진흙 땅이에요.","조개를 캘 수 있어요.","갯벌이에요."],"asset":{"type":"passage","lines":["바닷물이 빠지자 넓은 진흙 땅이 드러났다.","동생과 조개를 캤다.","지도를 보니 해안선이 들쭉날쭉하고 섬이 많았다."],"title":"새봄이네 수첩 ③ 진흙 바닷가"}}'::jsonb),
