('g5_1_soc_u1_review_a#8','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',1,'mc','auto','새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?',ARRAY['SO5-1-u1-X16','SO5-1-u1-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u1-C8","difficulty":1,"kind":"mc","stem":"새봄이네 수첩 ⑦에 나온 독도의 두 큰 섬은 무엇인가요?","options":[{"t":"동도와 서도","correct":true},{"t":"남도와 북도","mis":"SO5-1-u1-X16"},{"t":"울릉도와 제주도","mis":"SO5-1-u1-X14"},{"t":"큰섬과 작은섬","mis":"SO5-1-u1-X16"}],"explanation":["동쪽 섬과 서쪽 섬이에요.","동도와 서도예요.","주변에 바위섬이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb),
('g5_1_soc_u1_review_a#9','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C2',2,'mc','auto','새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u1-C2","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ①의 산지가 북동쪽에 있는 것과 가장 관계 깊은 우리나라 땅의 특징은 어느 것인가요?","options":[{"t":"높고 험한 산지가 북쪽과 동쪽에 몰려 있다","correct":true},{"t":"높은 산지가 남쪽과 서쪽에 몰려 있다","mis":"SO5-1-u1-X03"},{"t":"우리나라는 어디나 높이가 같다","mis":"SO5-1-u1-X03"},{"t":"높은 산지는 바다 한가운데에 있다","mis":"SO5-1-u1-X03"}],"explanation":["수첩 ①은 북동쪽이에요.","높은 산지가 북·동쪽에 있어요.","그래서 북동쪽이 높아요."],"asset":{"type":"passage","lines":["첫째 날 — 북동쪽의 높은 산지에 갔다.","험한 봉우리가 줄지어 있고 바람이 세게 불었다.","지형도에서 이곳은 진한 갈색으로 칠해져 있었다."],"title":"새봄이네 수첩 ① 높은 산"}}'::jsonb),
('g5_1_soc_u1_review_a#10','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',2,'mc','auto','새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X06','SO5-1-u1-X08']::text[],false,'{"seq":10,"concept":"SO5-1-u1-C3","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ②의 「아래쪽에는 논이 넓게 펼쳐져 있었다」는 모습이 생긴 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"하천 주변의 낮고 평평한 땅에 평야가 발달했기 때문에","correct":true},{"t":"높은 산꼭대기에 평야가 생겼기 때문에","mis":"SO5-1-u1-X06"},{"t":"바닷물이 빠져 진흙 땅이 드러났기 때문에","mis":"SO5-1-u1-X08"},{"t":"파도가 바위를 깎았기 때문에","mis":"SO5-1-u1-X08"}],"explanation":["하천 아래쪽은 낮아요.","평평한 땅이 넓어요.","평야에 논이 많아요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb),
('g5_1_soc_u1_review_a#11','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',2,'mc','auto','새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ③과 ④를 견주어 바르게 말한 것은 어느 것인가요?","options":[{"t":"③은 해안선이 들쭉날쭉하고 갯벌이 있고, ④는 해안선이 곧고 모래사장이 넓다","correct":true},{"t":"③은 모래사장이 넓고, ④는 갯벌이 넓다","mis":"SO5-1-u1-X07"},{"t":"③과 ④는 해안선 모습이 같다","mis":"SO5-1-u1-X07"},{"t":"③은 동해안, ④는 서해안의 모습이다","mis":"SO5-1-u1-X07"}],"explanation":["③은 갯벌과 복잡한 해안선이에요.","④는 곧은 해안선과 모래사장이에요.","바다마다 모습이 달라요."]}'::jsonb),
('g5_1_soc_u1_review_a#12','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C5',2,'mc','auto','새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑤에서 아빠가 동생을 말린 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오랜 시간이 만든 자연이라 가져가면 되돌릴 수 없기 때문에","correct":true},{"t":"돌 조각이 너무 무거워서","mis":"SO5-1-u1-X10"},{"t":"돌은 사서 가져가야 하기 때문에","mis":"SO5-1-u1-X10"},{"t":"해설사가 돌을 팔기 때문에","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원의 돌은 오랜 시간이 만들었어요.","가져가면 되돌릴 수 없어요.","눈으로만 봐요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb),
('g5_1_soc_u1_review_a#13','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',2,'mc','auto','새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"mc","stem":"새봄이네처럼 「산에서 바다까지 여러 지형을 만나는 여행」을 하려고 해요. 경로를 정할 때 알맞은 생각은 어느 것인가요?","options":[{"t":"이동 거리가 너무 길어지지 않게, 여행 목적에 맞는 차례로 화살표를 잇는다","correct":true},{"t":"가장 먼 곳끼리 번갈아 다닌다","mis":"SO5-1-u1-X11"},{"t":"조사하지 않은 곳을 많이 넣는다","mis":"SO5-1-u1-X11"},{"t":"여행지 이름만 나열하고 경로는 그리지 않는다","mis":"SO5-1-u1-X11"}],"explanation":["동선이 길지 않게 해요.","목적에 맞는 차례로 해요.","화살표로 이어요."]}'::jsonb),
('g5_1_soc_u1_review_a#14','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',2,'mc','auto','새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X16']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑥의 「맑은 날 전망대에서 멀리 독도가 보였다」가 뜻하는 것으로 알맞은 것은 어느 것인가요?","options":[{"t":"울릉도 사람들은 오래전부터 독도를 알고 우리 영토로 여겨 왔다","correct":true},{"t":"독도와 울릉도는 땅으로 이어져 있다","mis":"SO5-1-u1-X14"},{"t":"독도는 울릉도보다 훨씬 크다","mis":"SO5-1-u1-X16"},{"t":"독도에는 공항이 있다","mis":"SO5-1-u1-X14"}],"explanation":["눈에 보일 만큼 가까워요.","오래전부터 알았어요.","우리 영토로 여겼어요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb),
('g5_1_soc_u1_review_a#15','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C8',2,'mc','auto','새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑦에서 안개가 끼었다 걷힌 것과 관계 깊은 독도의 날씨 특징은 어느 것인가요?","options":[{"t":"대체로 온화하지만 안개가 자주 끼고 흐린 날이 많다","correct":true},{"t":"일 년 내내 눈이 쌓여 있다","mis":"SO5-1-u1-X16"},{"t":"비가 전혀 오지 않는다","mis":"SO5-1-u1-X16"},{"t":"사막처럼 늘 건조하다","mis":"SO5-1-u1-X16"}],"explanation":["독도는 바다 한가운데예요.","안개가 자주 껴요.","흐린 날이 많아요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb),
('g5_1_soc_u1_review_a#16','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',2,'mc','auto','새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 본 옛 지도로 알 수 있는 것은 어느 것인가요?","options":[{"t":"당시 일본에서도 독도를 조선의 영토로 여겼다","correct":true},{"t":"독도는 옛날에 일본 땅이었다","mis":"SO5-1-u1-X17"},{"t":"옛날에는 동해에 섬이 없었다","mis":"SO5-1-u1-X17"},{"t":"지도를 만든 나라는 조선이다","mis":"SO5-1-u1-X17"}],"explanation":["일본이 만든 지도예요.","독도를 조선 색으로 칠했어요.","일본도 조선 땅으로 여겼어요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb),
('g5_1_soc_u1_review_a#17','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',3,'mc','auto','새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X04']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ①에서 ②로 이어지는 여행을 지형도에 그린다면 물줄기를 따라간 방향으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"북동쪽의 진한 색 땅에서 서쪽의 옅은 색 땅으로","correct":true},{"t":"서쪽의 옅은 색 땅에서 북동쪽의 진한 색 땅으로","mis":"SO5-1-u1-X05"},{"t":"초록색 땅에서 진한 갈색 땅으로","mis":"SO5-1-u1-X04"},{"t":"높이가 같은 땅을 따라 옆으로만","mis":"SO5-1-u1-X05"}],"explanation":["물은 높은 곳에서 출발해요.","진한 색이 높은 곳이에요.","옅은 색 낮은 곳으로 흘러요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb),
('g5_1_soc_u1_review_a#18','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C4',3,'mc','auto','새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X08','SO5-1-u1-X07','SO5-1-u1-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ④의 바닷가에 서핑하는 사람과 해수욕장이 많은 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해안선이 단순하고 넓은 모래사장이 펼쳐진 동해안이기 때문에","correct":true},{"t":"물이 빠지면 넓은 갯벌이 드러나기 때문에","mis":"SO5-1-u1-X08"},{"t":"섬이 아주 많아 다도해이기 때문에","mis":"SO5-1-u1-X07"},{"t":"높은 산지 위에 있기 때문에","mis":"SO5-1-u1-X09"}],"explanation":["모래사장이 넓어요.","해수욕장이 발달해요.","파도를 타기도 좋아요."],"asset":{"type":"passage","lines":["해안선이 곧게 뻗은 바닷가에 갔다.","넓은 모래사장에서 해수욕을 했다.","파도를 타며 서핑을 하는 사람도 많았다."],"title":"새봄이네 수첩 ④ 모래 바닷가"}}'::jsonb),
('g5_1_soc_u1_review_a#19','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C6',3,'mc','auto','새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"새봄이가 「다양한 해안 지형을 견주어 보는 여행」을 주제로 다시 계획한다면 넣기 가장 알맞은 수첩 꼭지 묶음은 어느 것인가요?","options":[{"t":"③과 ④","correct":true},{"t":"①과 ②","mis":"SO5-1-u1-X09"},{"t":"⑥과 ⑧","mis":"SO5-1-u1-X09"},{"t":"①과 ⑤","mis":"SO5-1-u1-X09"}],"explanation":["해안 지형을 견주어요.","③은 갯벌, ④는 모래사장이에요.","두 바닷가를 넣어요."]}'::jsonb),
('g5_1_soc_u1_review_a#20','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',3,'mc','auto','새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑦을 함께 볼 때 다른 나라 사람이 독도에 간다면 어떻게 가야 할까요?","options":[{"t":"우리나라에 들어와 동해안 항구에서 배를 타고 울릉도를 거쳐 간다","correct":true},{"t":"자기 나라에서 비행기로 독도에 바로 간다","mis":"SO5-1-u1-X14"},{"t":"아무 나라에서나 배를 타고 바로 간다","mis":"SO5-1-u1-X14"},{"t":"다른 나라 사람은 독도에 갈 수 없다","mis":"SO5-1-u1-X15"}],"explanation":["독도는 우리 영토예요.","우리와 같은 방법으로 가요.","항구 → 울릉도 → 독도예요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb),
('g5_1_soc_u1_review_a#21','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C9',3,'mc','auto','새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?',ARRAY['SO5-1-u1-X17','SO5-1-u1-X13']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧의 옛 지도가 독도가 우리 땅이라는 증거로 특히 힘이 있는 까닭은 어느 것인가요?","options":[{"t":"자기 나라 땅이라 할 수도 있었던 일본이 독도를 조선 색으로 칠했기 때문에","correct":true},{"t":"지도가 아주 크고 화려하기 때문에","mis":"SO5-1-u1-X17"},{"t":"우리나라가 만든 지도이기 때문에","mis":"SO5-1-u1-X17"},{"t":"연도가 가장 정확하게 적혀 있기 때문에","mis":"SO5-1-u1-X13"}],"explanation":["만든 나라가 일본이에요.","그런데도 조선 색이에요.","그래서 더 믿을 만해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb),
('g5_1_soc_u1_review_a#22','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C11',3,'mc','auto','새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?',ARRAY['SO5-1-u1-X19','SO5-1-u1-X16']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑧에서 새봄이가 독도를 알리는 그림을 만들 때 넣기 가장 알맞은 조건은 어느 것인가요?","options":[{"t":"동도와 서도 사이를 나는 괭이갈매기와 바위에 핀 해국","correct":true},{"t":"예쁜 풍경","mis":"SO5-1-u1-X19"},{"t":"산 위 목장에서 풀을 뜯는 소","mis":"SO5-1-u1-X16"},{"t":"넓은 모래사장의 해수욕장","mis":"SO5-1-u1-X16"}],"explanation":["수첩 ⑦에서 본 것을 떠올려요.","독도의 모습을 자세히 적어요.","흐린 조건은 안 돼요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb),
('g5_1_soc_u1_review_a#23','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C1',4,'mc','auto','「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X03','SO5-1-u1-X13','SO5-1-u1-X05']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C1","difficulty":4,"kind":"mc","stem":"「우리나라 국토 여행」 단원에서 배운 내용을 가장 잘 정리한 것은 어느 것인가요?","options":[{"t":"우리 국토는 북동쪽이 높고 남서쪽이 낮아 산지·하천·평야·해안이 어우러지고, 동쪽 끝 독도는 예로부터 우리 땅으로 함께 지켜 왔다","correct":true},{"t":"우리 국토는 어디나 평평하고 독도는 최근에 알려진 섬이다","mis":"SO5-1-u1-X03"},{"t":"지형은 이름만 외우면 되고 독도는 정부만 지키면 된다","mis":"SO5-1-u1-X13"},{"t":"하천은 동쪽으로 흐르고 독도는 서쪽 끝에 있다","mis":"SO5-1-u1-X05"}],"explanation":["높낮이가 지형을 이어 줘요.","독도는 동쪽 끝이에요.","옛날부터 함께 지켜 왔어요."]}'::jsonb),
('g5_1_soc_u1_review_a#24','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C3',4,'essay','teacher','새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C3","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①과 ②를 보고 물줄기가 서쪽으로 흘러간 까닭을 우리나라 땅의 높낮이와 함께 쓰고, 물줄기 아래쪽에 논이 넓게 펼쳐진 까닭을 쓰세요.","answer_guide":{"answer":"예: 우리나라는 높고 험한 산지가 북쪽과 동쪽에 몰려 있어 북동쪽이 높고 남서쪽이 낮다. 물은 높은 곳에서 낮은 곳으로 흐르므로 북동쪽 산에서 시작한 계곡물이 낮은 서쪽으로 흘러갔다. 물줄기 아래쪽은 낮고 평평한 땅이어서 평야가 발달했고 그래서 논이 넓게 펼쳐져 있다.","scoring_points":["북동쪽이 높고 남서쪽이 낮다고 썼는가","물이 낮은 곳으로 흐른다는 까닭을 썼는가","하천 주변 평야와 논을 이어 썼는가"]},"explanation":["높낮이가 방향을 정해요.","물은 낮은 곳으로 흘러요.","하천 주변에 평야가 있어요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb),
('g5_1_soc_u1_review_a#25','soc',5,1,'u1','','g5_1_soc_u1_review_a','unit_review','SO5-1-u1-C7',4,'essay','teacher','새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C7","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑥을 보고 독도까지 가는 길을 차례대로 쓰고, 독도의 위치를 쓴 뒤, 독도가 중요한 까닭을 두 가지 쓰세요.","answer_guide":{"answer":"예: 동해안의 항구에서 배를 타고 울릉도에 간 뒤 다시 배를 타고 독도로 간다. 독도에는 공항이 없기 때문이다. 독도는 우리나라 영토의 동쪽 끝, 동해에 있다. 독도는 우리 영토의 동쪽 경계를 알려 주고, 우리나라·일본·러시아로 둘러싸인 동해에 있어 교통과 군사 면에서 중요하다.","scoring_points":["항구 → 울릉도 → 독도의 차례를 썼는가","위치를 썼는가","중요한 까닭 두 가지를 썼는가"]},"explanation":["배로 울릉도를 거쳐요.","동쪽 끝이에요.","경계·교통·군사·연구·자원이에요."],"asset":{"type":"passage","lines":["동해안 항구에서 배를 타고 울릉도에 갔다.","맑은 날 전망대에서 멀리 독도가 보였다.","다음 날 다시 배를 타고 독도로 향했다."],"title":"새봄이네 수첩 ⑥ 독도 가는 길"}}'::jsonb),
