('g5_1_soc_u1_review_c#11','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C4',2,'ox','auto','남해안은 섬이 아주 많아 다도해라고도 불러요.',ARRAY['SO5-1-u1-X07']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"ox","stem":"남해안은 섬이 아주 많아 다도해라고도 불러요.","answer":"O","reason_options":[{"t":"해안선이 복잡하고 크고 작은 섬이 많기 때문에","correct":true},{"t":"남해안에는 섬이 하나도 없기 때문에","mis":"SO5-1-u1-X07"}],"mis":"SO5-1-u1-X07","explanation":["남해안은 섬이 많아요.","다도해라고 불러요.","해안선도 복잡해요."]}'::jsonb),
('g5_1_soc_u1_review_c#12','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',2,'ox','auto','파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.',ARRAY['SO5-1-u1-X09']::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"ox","stem":"파도가 바위를 깎아 만든 절벽과 동굴은 하천이 만든 경관이에요.","answer":"X","reason_options":[{"t":"바닷가에서 파도가 만든 해안의 경관이기 때문에","correct":true},{"t":"절벽과 동굴은 높은 산에서만 생기기 때문에","mis":"SO5-1-u1-X09"}],"mis":"SO5-1-u1-X09","explanation":["파도는 바다에서 쳐요.","해안의 바위를 깎아요.","해안이 만든 경관이에요."]}'::jsonb),
