('g5_1_soc_u1_review_c#14','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C7',2,'ox','auto','독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.',ARRAY['SO5-1-u1-X14']::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"ox","stem":"독도는 우리 영토의 동쪽 경계를 알려 주는 섬이에요.","answer":"O","reason_options":[{"t":"우리나라 영토의 동쪽 끝에 있기 때문에","correct":true},{"t":"독도는 우리 영토의 서쪽 끝에 있기 때문에","mis":"SO5-1-u1-X14"}],"mis":"SO5-1-u1-X14","explanation":["독도는 동쪽 끝이에요.","영토의 경계를 알려요.","그래서 중요해요."]}'::jsonb),
('g5_1_soc_u1_review_c#15','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',2,'ox','auto','독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.',ARRAY['SO5-1-u1-X16']::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"ox","stem":"독도 바다 밑에는 「불타는 얼음」이라 불리는 가스 하이드레이트가 묻혀 있어요.","answer":"O","reason_options":[{"t":"고체 형태의 천연가스가 바다 밑바닥에 묻혀 있기 때문에","correct":true},{"t":"가스 하이드레이트는 바다 위에 떠다니는 얼음이기 때문에","mis":"SO5-1-u1-X16"}],"mis":"SO5-1-u1-X16","explanation":["고체로 된 천연가스예요.","바다 밑에 있어요.","미래 에너지 자원이에요."]}'::jsonb),
('g5_1_soc_u1_review_c#16','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',2,'ox','auto','「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C9","difficulty":2,"kind":"ox","stem":"「태정관 지령」은 일본이 만든 문서인데도 울릉도와 독도가 일본 땅이 아니라고 밝혔어요.","answer":"O","reason_options":[{"t":"일본 스스로 두 섬이 자기 나라 땅이 아니라고 적은 국가 문서이기 때문에","correct":true},{"t":"「태정관 지령」은 우리나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["일본의 국가 문서예요.","두 섬이 일본 땅이 아니라고 했어요.","그래서 더 분명한 증거예요."]}'::jsonb),
('g5_1_soc_u1_review_c#17','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C3',3,'error','auto','새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u1-X05','SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"error","stem":"새봄이네 수첩 ②를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤호 — 「물줄기가 서쪽으로 간 걸 보니 서쪽 땅이 더 높아.」","correct":true,"mis_target":"SO5-1-u1-X05"},{"t":"가은 — 「물줄기 아래쪽의 논은 평야에 있어.」","mis":"SO5-1-u1-X06"},{"t":"태린 — 「계곡물은 높은 산지에서 시작했어.」","mis":"SO5-1-u1-X05"}],"explanation":["물은 낮은 곳으로 흘러요.","서쪽으로 갔다면 서쪽이 낮아요.","윤호의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["산에서 시작한 계곡물을 따라 차로 내려왔다.","물줄기는 점점 서쪽의 낮은 곳으로 흘러갔다.","아래쪽에는 논이 넓게 펼쳐져 있었다."],"title":"새봄이네 수첩 ② 물줄기를 따라"}}'::jsonb),
('g5_1_soc_u1_review_c#18','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',3,'mc','auto','새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X10']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C5","difficulty":3,"kind":"mc","stem":"새봄이네 수첩 ⑤처럼 지질 공원에서 지켜야 할 태도로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"해설을 들으며 눈으로 보고 마음에 담되 자연물은 그대로 둔다","correct":true},{"t":"기념으로 작은 돌 조각을 가져간다","mis":"SO5-1-u1-X10"},{"t":"바위에 이름을 새겨 다녀간 표시를 한다","mis":"SO5-1-u1-X10"},{"t":"해설은 듣지 않고 사진만 찍는다","mis":"SO5-1-u1-X10"}],"explanation":["지질 공원은 보전하는 곳이에요.","보고 배워요.","자연물은 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb),
('g5_1_soc_u1_review_c#19','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C6',3,'mc','auto','친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"mc","stem":"친구의 계획서에 남길 댓글로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"「해 질 녘 해안 사진이 정말 아름다워요. 저도 가 보고 싶어요!」","correct":true},{"t":"「이게 무슨 여행이야, 재미없겠다.」","mis":"SO5-1-u1-X12"},{"t":"「글씨가 엉망이네, 다시 써.」","mis":"SO5-1-u1-X12"},{"t":"「ㅋㅋㅋ」","mis":"SO5-1-u1-X12"}],"explanation":["느낀 점을 예의 있게 써요.","좋은 점을 칭찬해요.","놀리는 말은 안 돼요."]}'::jsonb),
('g5_1_soc_u1_review_c#20','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C8',3,'mc','auto','독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?',ARRAY['SO5-1-u1-X14','SO5-1-u1-X10','SO5-1-u1-X16']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C8","difficulty":3,"kind":"mc","stem":"독도에 사는 새와 식물, 주변 바다 생물을 함께 지키려고 우리나라가 한 일은 어느 것인가요?","options":[{"t":"독도 전체를 천연기념물로 지정했다","correct":true},{"t":"독도에 큰 공항을 지었다","mis":"SO5-1-u1-X14"},{"t":"독도 바위를 캐어 박물관에 옮겼다","mis":"SO5-1-u1-X10"},{"t":"독도의 새를 모두 다른 섬으로 옮겼다","mis":"SO5-1-u1-X16"}],"explanation":["생물은 서로 이어져 있어요.","전체를 지켜야 해요.","천연기념물로 지정했어요."]}'::jsonb),
('g5_1_soc_u1_review_c#21','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',3,'mc','auto','「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"mc","stem":"「조선왕국전도」와 「팔도총도」를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"조선 사람뿐 아니라 멀리 유럽 사람들도 동해에 울릉도와 독도가 있음을 알았다","correct":true},{"t":"두 지도 모두 일본에서 만들었다","mis":"SO5-1-u1-X17"},{"t":"두 지도에는 독도가 그려지지 않았다","mis":"SO5-1-u1-X17"},{"t":"유럽 사람만 독도를 알았다","mis":"SO5-1-u1-X17"}],"explanation":["「팔도총도」는 우리 지도예요.","「조선왕국전도」는 프랑스 지도예요.","두 섬을 모두 그렸어요."]}'::jsonb),
('g5_1_soc_u1_review_c#22','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C10',3,'mc','auto','정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C10","difficulty":3,"kind":"mc","stem":"정부가 독도에 선착장·주민 숙소·등대를 만든 것의 뜻으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"사람이 오가고 머물며 독도를 우리 땅으로 다스리는 데 필요한 시설을 갖춘 것이다","correct":true},{"t":"독도를 다른 나라에 빌려주려는 것이다","mis":"SO5-1-u1-X18"},{"t":"독도의 바위를 캐내려는 것이다","mis":"SO5-1-u1-X10"},{"t":"독도에 아무도 오지 못하게 하려는 것이다","mis":"SO5-1-u1-X18"}],"explanation":["시설이 있어야 오갈 수 있어요.","주민과 경비대가 머물러요.","우리 땅으로 다스려요."]}'::jsonb),
('g5_1_soc_u1_review_c#23','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'mc','auto','새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?',ARRAY['SO5-1-u1-X15','SO5-1-u1-X16','SO5-1-u1-X17']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑥과 ⑧을 함께 볼 때 독도가 우리 땅임을 보여 주는 근거를 가장 잘 묶은 것은 어느 것인가요?","options":[{"t":"울릉도에서 눈으로 보일 만큼 가까워 예로부터 알았고, 일본이 만든 옛 지도도 조선 땅으로 나타냈다","correct":true},{"t":"독도에는 공항이 없고 안개가 자주 낀다","mis":"SO5-1-u1-X15"},{"t":"독도는 화산섬이라 바위가 많다","mis":"SO5-1-u1-X16"},{"t":"새봄이가 독도를 알리는 그림을 그리기로 했다","mis":"SO5-1-u1-X17"}],"explanation":["⑥ — 보이는 거리예요.","⑧ — 다른 나라 지도예요.","둘 다 영토의 근거예요."]}'::jsonb),
('g5_1_soc_u1_review_c#24','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C5',4,'essay','teacher','새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C5","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑤에서 지질 공원 해설사가 한 일을 쓰고, 동생의 행동이 왜 바르지 않은지 쓴 뒤, 지질 공원을 지키려고 내가 할 수 있는 일을 쓰세요.","answer_guide":{"answer":"예: 해설사는 바위가 생긴 까닭과 마을의 옛이야기를 엮어 알기 쉽게 설명해 주었다. 지질 공원의 돌은 오랜 시간이 만든 단 하나뿐인 자연이라 가져가면 되돌릴 수 없으므로 동생의 행동은 바르지 않다. 나는 해설을 귀 기울여 듣고, 바위를 만지거나 가져가지 않고 눈으로만 보며, 쓰레기를 되가져오겠다.","scoring_points":["해설사가 한 일을 썼는가","동생의 행동이 바르지 않은 까닭을 썼는가","내가 할 수 있는 일을 썼는가"]},"explanation":["해설사는 엮어서 설명해요.","자연물은 되돌릴 수 없어요.","보고 배우되 그대로 둬요."],"asset":{"type":"passage","lines":["해설사 선생님이 바위가 생긴 까닭과 마을 옛이야기를 들려주셨다.","동생이 예쁜 돌 조각을 주머니에 넣으려 했다.","아빠가 「눈으로만 보자」며 말리셨다."],"title":"새봄이네 수첩 ⑤ 지질 공원"}}'::jsonb),
('g5_1_soc_u1_review_c#25','soc',5,1,'u1','','g5_1_soc_u1_review_c','unit_review','SO5-1-u1-C9',4,'essay','teacher','새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C9","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ⑧에 나온 옛 지도와 사람 이야기가 각각 무엇을 말해 주는지 쓰고, 이 둘이 독도가 우리 땅이라는 근거가 되는 까닭을 쓰세요.","answer_guide":{"answer":"예: 일본이 만든 옛 지도는 독도를 조선과 같은 색으로 칠해 당시 일본도 독도를 조선의 영토로 여겼음을 보여 준다. 안용복 이야기는 조선 사람이 일본에 건너가 두 섬이 조선 땅이라고 설명했고 일본도 이를 인정했음을 보여 준다. 다른 나라가 만든 자료와 옛사람의 노력 모두 독도를 우리 땅으로 나타내므로 우리 땅이라는 근거가 된다.","scoring_points":["옛 지도가 말하는 것을 썼는가","안용복 이야기가 말하는 것을 썼는가","두 가지가 근거가 되는 까닭을 썼는가"]},"explanation":["지도는 일본이 만들었어요.","안용복은 일본에 건너가 설명했어요.","둘 다 우리 땅을 보여 줘요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb),
('g5_1_soc_u1_review_d#1','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C1',1,'ox','auto','둘레가 바다로 둘러싸인 땅을 섬이라고 해요.',ARRAY['SO5-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u1-C1","difficulty":1,"kind":"ox","stem":"둘레가 바다로 둘러싸인 땅을 섬이라고 해요.","answer":"O","reason_options":[{"t":"사방이 바다와 맞닿아 있는 땅이기 때문에","correct":true},{"t":"섬은 하천 주변의 넓은 땅이기 때문에","mis":"SO5-1-u1-X02"}],"mis":"SO5-1-u1-X02","explanation":["섬은 바다에 둘러싸여요.","배를 타고 가요.","독도도 섬이에요."]}'::jsonb),
