('g5_1_soc_u1_review_d#11','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',2,'mc','auto','갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?',ARRAY['SO5-1-u1-X07','SO5-1-u1-X09','SO5-1-u1-X06']::text[],false,'{"seq":11,"concept":"SO5-1-u1-C4","difficulty":2,"kind":"mc","stem":"갯벌을 막아 논이나 공장 땅으로 쓰는 일은 어느 해안에서 주로 볼 수 있나요?","options":[{"t":"서해안","correct":true},{"t":"동해안","mis":"SO5-1-u1-X07"},{"t":"높은 산지","mis":"SO5-1-u1-X09"},{"t":"하천의 상류","mis":"SO5-1-u1-X06"}],"explanation":["갯벌을 막는 일이에요.","갯벌은 서해안에 넓어요.","간척이라고 해요."]}'::jsonb),
('g5_1_soc_u1_review_d#12','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C5',2,'match','auto','경관과 그 경관을 만든 지형을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO5-1-u1-C5","difficulty":2,"kind":"match","stem":"경관과 그 경관을 만든 지형을 알맞게 이으세요.","pairs":[{"l":"바위 봉우리와 폭포가 있는 산","r":"산지"},{"l":"지평선이 보이는 들판","r":"평야"},{"l":"갯벌과 갈대밭이 펼쳐진 습지","r":"해안"}],"mis":"SO5-1-u1-X09","explanation":["봉우리와 폭포는 산지예요.","넓은 들판은 평야예요.","갯벌과 갈대밭은 해안이에요."]}'::jsonb),
('g5_1_soc_u1_review_d#13','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',2,'sa','auto','여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)','{}'::text[],false,'{"seq":13,"concept":"SO5-1-u1-C6","difficulty":2,"kind":"sa","stem":"여행 계획서를 사진으로 찍어 올려 친구들과 나눌 때 쓰는 도구를 무엇이라고 하나요? (□□ □□□□□□)","answer":["공유 애플리케이션","공유애플리케이션","공유 앱"],"explanation":["함께 나누는 도구예요.","자리에서 언제든 볼 수 있어요.","공유 애플리케이션이에요."],"mis":"SO5-1-u1-X11"}'::jsonb),
('g5_1_soc_u1_review_d#14','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',2,'sa','auto','독도가 있는 바다의 이름을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO5-1-u1-C7","difficulty":2,"kind":"sa","stem":"독도가 있는 바다의 이름을 두 글자로 쓰세요.","answer":["동해"],"explanation":["우리나라 동쪽 바다예요.","세 나라가 둘러싸요.","동해예요."],"mis":"SO5-1-u1-X14"}'::jsonb),
('g5_1_soc_u1_review_d#15','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C8',2,'match','auto','독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO5-1-u1-C8","difficulty":2,"kind":"match","stem":"독도에서 볼 수 있는 것과 그 갈래를 알맞게 이으세요.","pairs":[{"l":"괭이갈매기","r":"새"},{"l":"해국","r":"식물"},{"l":"해양 심층수","r":"바다 자원"}],"mis":"SO5-1-u1-X16","explanation":["괭이갈매기는 새예요.","해국은 바위에 피는 식물이에요.","해양 심층수는 바다 자원이에요."],"asset":{"type":"passage","lines":["동도와 서도 사이로 괭이갈매기가 날았다.","바위에는 해국이 피어 있었고 안개가 끼었다 걷혔다.","독도 경비대원이 배에서 내리는 사람들을 안내했다."],"title":"새봄이네 수첩 ⑦ 독도"}}'::jsonb),
('g5_1_soc_u1_review_d#16','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',2,'mc','auto','홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?',ARRAY['SO5-1-u1-X18','SO5-1-u1-X10']::text[],false,'{"seq":16,"concept":"SO5-1-u1-C10","difficulty":2,"kind":"mc","stem":"홍순칠과 울릉도 청년들이 독도를 지키려고 만든 모임은 어느 것인가요?","options":[{"t":"독도 의용 수비대","correct":true},{"t":"독도 경비대","mis":"SO5-1-u1-X18"},{"t":"사이버 외교 사절단","mis":"SO5-1-u1-X18"},{"t":"지질 공원 해설단","mis":"SO5-1-u1-X10"}],"explanation":["울릉도 청년들이 함께했어요.","스스로 독도를 지켰어요.","독도 의용 수비대예요."]}'::jsonb),
('g5_1_soc_u1_review_d#17','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C3',3,'ox','auto','평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.',ARRAY['SO5-1-u1-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u1-C3","difficulty":3,"kind":"ox","stem":"평야가 하천 주변에 발달한 것과 우리나라 땅이 북동쪽은 높고 남서쪽은 낮은 것은 서로 관계가 있어요.","answer":"O","reason_options":[{"t":"높낮이가 하천의 방향을 정하고 하천이 흐르는 낮은 땅 주변에 평야가 펼쳐지기 때문에","correct":true},{"t":"평야는 땅의 높낮이와 상관없이 아무 데나 생기기 때문에","mis":"SO5-1-u1-X06"}],"mis":"SO5-1-u1-X06","explanation":["높낮이 → 하천의 방향이에요.","하천이 흐르는 곳은 낮아요.","그 주변에 평야가 생겨요."]}'::jsonb),
('g5_1_soc_u1_review_d#18','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C4',3,'ox','auto','해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.',ARRAY['SO5-1-u1-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u1-C4","difficulty":3,"kind":"ox","stem":"해안의 모습에 따라 해산물을 얻는 곳, 해수욕장, 간척지처럼 사람들의 생활 모습이 달라져요.","answer":"O","reason_options":[{"t":"갯벌·모래사장 같은 해안 지형을 생활에 맞게 이용하기 때문에","correct":true},{"t":"해안 사람들은 지형과 상관없이 똑같이 살기 때문에","mis":"SO5-1-u1-X08"}],"mis":"SO5-1-u1-X08","explanation":["지형에 맞게 살아요.","갯벌에서는 해산물, 모래사장에서는 해수욕이에요.","간척도 해요."]}'::jsonb),
('g5_1_soc_u1_review_d#19','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',3,'ox','auto','새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.',ARRAY['SO5-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO5-1-u1-C6","difficulty":3,"kind":"ox","stem":"새봄이네처럼 여러 지역을 두루 다니는 여행은 우리나라 전체 지도에, 한 지역 안의 여행은 그 지역 백지도에 경로를 그리는 것이 알맞아요.","answer":"O","reason_options":[{"t":"경로의 넓이에 맞는 지도를 써야 알아보기 쉽기 때문에","correct":true},{"t":"어떤 여행이든 지도는 쓰지 않는 것이 좋기 때문에","mis":"SO5-1-u1-X11"}],"mis":"SO5-1-u1-X11","explanation":["넓은 여행은 전국 지도예요.","좁은 여행은 그 지역 백지도예요.","알아보기 쉬운 지도를 써요."]}'::jsonb),
('g5_1_soc_u1_review_d#20','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C7',3,'ox','auto','독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.',ARRAY['SO5-1-u1-X15']::text[],false,'{"seq":20,"concept":"SO5-1-u1-C7","difficulty":3,"kind":"ox","stem":"독도 주변 바다는 어업을 하는 우리 국민을 보호하고 배가 급할 때 대피할 수 있는 곳이기도 해요.","answer":"O","reason_options":[{"t":"동해 한가운데의 섬이라 바다에서 일하는 사람들을 지켜 줄 수 있기 때문에","correct":true},{"t":"독도 주변에서는 배가 다닐 수 없기 때문에","mis":"SO5-1-u1-X15"}],"mis":"SO5-1-u1-X15","explanation":["독도는 바다 한가운데예요.","어업하는 국민을 지켜요.","급할 때 피할 수 있어요."]}'::jsonb),
('g5_1_soc_u1_review_d#21','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C9',3,'ox','auto','대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.',ARRAY['SO5-1-u1-X17']::text[],false,'{"seq":21,"concept":"SO5-1-u1-C9","difficulty":3,"kind":"ox","stem":"대한 제국이 칙령으로 독도를 울릉군이 다스린다고 정한 것은 독도가 우리 땅임을 나라가 분명히 밝힌 기록이에요.","answer":"O","reason_options":[{"t":"나라가 공식 문서로 독도를 다스리는 곳을 정했기 때문에","correct":true},{"t":"칙령은 다른 나라가 만든 문서이기 때문에","mis":"SO5-1-u1-X17"}],"mis":"SO5-1-u1-X17","explanation":["칙령은 나라의 명령이에요.","울릉군이 독도를 다스려요.","10월 25일 독도의 날이 됐어요."]}'::jsonb),
('g5_1_soc_u1_review_d#22','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',3,'ox','auto','인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.',ARRAY['SO5-1-u1-X19']::text[],false,'{"seq":22,"concept":"SO5-1-u1-C11","difficulty":3,"kind":"ox","stem":"인공지능으로 만든 그림이 마음에 들지 않으면 조건을 더하거나 바꾸어 다시 만들면 돼요.","answer":"O","reason_options":[{"t":"조건을 고칠수록 원하는 그림에 가까워지기 때문에","correct":true},{"t":"한 번 만든 그림은 다시 만들 수 없기 때문에","mis":"SO5-1-u1-X19"}],"mis":"SO5-1-u1-X19","explanation":["고칠 수 있는 것은 조건이에요.","여러 번 다시 만들어요.","마음에 들 때까지 해요."]}'::jsonb),
('g5_1_soc_u1_review_d#23','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C10',4,'mc','auto','새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?',ARRAY['SO5-1-u1-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u1-C10","difficulty":4,"kind":"mc","stem":"새봄이네 수첩 ⑦과 ⑧을 함께 볼 때 독도를 지키는 사람들을 가장 잘 말한 것은 어느 것인가요?","options":[{"t":"옛날의 안용복부터 오늘의 독도 경비대, 그리고 독도를 알리려는 새봄이까지 모두가 지킨다","correct":true},{"t":"독도 경비대 혼자서만 지킨다","mis":"SO5-1-u1-X18"},{"t":"옛날 사람들만 지켰고 지금은 아무도 지키지 않는다","mis":"SO5-1-u1-X18"},{"t":"관광객은 독도를 지키는 일과 관계없다","mis":"SO5-1-u1-X18"}],"explanation":["옛사람과 오늘의 경비대가 있어요.","새봄이도 알리기로 했어요.","모두가 함께 지켜요."]}'::jsonb),
('g5_1_soc_u1_review_d#24','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C6',4,'essay','teacher','새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u1-C6","difficulty":4,"kind":"essay","stem":"새봄이네 수첩 ①~④를 참고해 「여러 지형을 만나는 국토 여행」 계획을 세우세요. 주제와 까닭, 여행지 두 곳과 지형, 경로를 정할 때 생각할 점을 쓰세요.","answer_guide":{"answer":"예: 나의 주제는 「산에서 바다까지 물을 따라가는 여행」이다. 땅의 높낮이가 지형을 어떻게 만드는지 직접 보고 싶기 때문이다. 먼저 북동쪽의 높은 산지에서 계곡을 보고, 물줄기를 따라 내려가 넓은 평야를 본 뒤 서해안의 갯벌에 가겠다. 경로는 이동 거리가 너무 길어지지 않게 물이 흐르는 차례에 맞추어 화살표로 잇겠다.","scoring_points":["주제와 까닭을 썼는가","여행지와 지형을 맞게 썼는가","경로를 정할 때 생각할 점을 썼는가"]},"explanation":["주제를 먼저 정해요.","여행지의 지형을 써요.","동선과 목적을 생각해요."]}'::jsonb),
('g5_1_soc_u1_review_d#25','soc',5,1,'u1','','g5_1_soc_u1_review_d','unit_review','SO5-1-u1-C11',4,'essay','teacher','새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u1-C11","difficulty":4,"kind":"essay","stem":"새봄이처럼 독도를 알리는 그림을 인공지능으로 만든다고 생각하고, 그림 이름과 자세한 조건 세 가지를 쓴 뒤, 친구들에게 소개할 말을 쓰세요.","answer_guide":{"answer":"예: 그림 이름은 「안개 걷힌 아침의 독도」이다. 조건은 ① 동도와 서도가 나란히 보이는 바다, ② 하늘을 나는 괭이갈매기 무리, ③ 바위에 핀 해국과 사철나무이다. 소개할 말: 「제 그림의 이름은 「안개 걷힌 아침의 독도」입니다. 동도와 서도, 괭이갈매기, 바위에 핀 해국을 조건으로 독도의 아름다운 자연을 표현했습니다.」","scoring_points":["그림 이름을 붙였는가","독도에 맞는 자세한 조건 세 가지를 썼는가","조건과 표현한 것을 넣어 소개했는가"]},"explanation":["이름을 붙여요.","조건은 자세하게 써요.","무엇을 표현했는지 소개해요."],"asset":{"type":"passage","lines":["일본이 만든 옛 지도에 독도가 조선과 같은 색으로 칠해져 있었다.","조선 시대에 일본에 건너가 두 섬이 조선 땅이라고 말한 사람 이야기를 들었다.","나도 독도를 알리는 그림을 만들어 보기로 했다."],"title":"새봄이네 수첩 ⑧ 독도 박물관"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('SO5-1-u2-C1','soc',5,1,'u2',1,'날씨와 기후 — 날씨는 짧은 시간 동안의 대기(공기) 상태로 하루 사이에도 바뀌고, 기후는 오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태 · 기후를 구성하는 요소는 기온(공기의 따뜻하고 차가운 정도)·강수(비·눈처럼 땅에 내린 물)·바람(공기가 움직이는 현상)이고 여러 해에 걸친 기록을 모아야 드러남 · 「사계절이 뚜렷하다」는 기후, 「오늘은 맑다」는 날씨',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],1),
('SO5-1-u2-C2','soc',5,1,'u2',1,'기후와 생활 — 기후는 의식주 생활과 산업 발전에 영향을 줌(기온이 높고 비가 많은 곳은 벼농사가 활발해 쌀 음식이 발달, 바람이 강한 곳은 바람으로 전기를 만드는 시설, 계절에 맞는 옷, 눈이 많은 겨울에 여는 축제) · 하루의 비로 행사를 못 하는 것은 날씨의 영향이고, 여러 해 되풀이되는 모습에 맞춘 생활이 기후의 영향',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],2),
('SO5-1-u2-C3','soc',5,1,'u2',2,'계절에 따른 바람과 기온 — 여름에는 남쪽 바다에서 뜨겁고 습한 바람이, 겨울에는 북서쪽 육지에서 차갑고 건조한 바람이 불어옴(바람이 지나온 곳이 바다냐 육지냐가 성질을 정함) · 우리나라는 남북으로 길어 대체로 남쪽으로 갈수록 기온이 높고, 남북 기온 차이는 여름보다 겨울에 훨씬 큼(여름엔 모두 덥고 겨울엔 북쪽만 크게 추워짐) · 등온선은 기온이 같은 곳을 이은 선',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],3),
('SO5-1-u2-C4','soc',5,1,'u2',2,'강수의 분포와 계절 — 연 강수량은 대체로 남쪽으로 갈수록 많아짐(분포도의 파란색이 진할수록 많음) · 계절로는 여름에 연 강수량의 절반 이상이 내리고 겨울에는 대체로 적음 · 봄은 온화하고 건조, 여름은 덥고 비가 잦음, 가을은 맑고 건조, 겨울은 춥고 건조하며 눈이 옴 — 통계 지도와 그래프에서 읽어 냄',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],4),
('SO5-1-u2-C5','soc',5,1,'u2',3,'계절별 자연재해 — 자연재해는 피할 수 없는 자연 현상으로 사람들이 입는 생명이나 재산상의 피해(자연 현상만으로는 재해가 아님) · 계절마다 바람·기온·강수가 달라 자주 생기는 재해도 다름: 봄 — 황사(사막의 모래 먼지가 바람을 타고 옴)·가뭄, 여름 — 폭염·호우(비가 많이 내림)·홍수(물이 흘러넘침), 여름과 가을 사이 — 태풍(많은 비와 강한 바람, 대체로 남서쪽에서 북동쪽으로), 겨울 — 폭설·한파',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],5),
('SO5-1-u2-C6','soc',5,1,'u2',3,'자연재해 피해를 줄이는 노력 — 자연재해는 막을 수 없지만 피해는 줄일 수 있음 · 저수지·댐·제방 같은 시설을 마련하고 재난 대비 훈련을 함 · 기상 특보(주의보·경보로 미리 알리는 정보)와 긴급 재난 문자로 알림 · 국민 행동 요령은 어린이를 포함한 국민 누구나 알고 실천함(태풍 때 외출 삼가기·시설물 정리) · 숲을 농경지로 일구거나 물길을 바꾸면 피해가 커지기도 함 · 예보 분석관이 날씨를 예측함',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],6),
('SO5-1-u2-C7','soc',5,1,'u2',4,'기후변화와 심해지는 자연재해 — 숲 파괴·석유와 석탄을 지나치게 쓰는 인간 활동으로 지구 온난화(지구의 기온이 높아지는 현상)가 심해져 전 세계에 기후변화가 나타남 · 우리나라는 연평균 기온이 꾸준히 올라가고(약 백 년 동안 1.9 ℃) 여름은 길어지고 겨울은 짧아짐 · 자연재해를 예측하기 어려워지고 강도가 세지며 횟수도 늘어 피해가 커짐(폭염·이상 고온·극한 호우·예측이 어려운 태풍)',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],7),
('SO5-1-u2-C8','soc',5,1,'u2',4,'기후 행동 — 기후변화를 막으려는 모든 노력 · 세계 여러 나라(파리 협정으로 기온 상승을 막기로 약속)·정부와 국회(기구 설치, 법과 제도)·기업(친환경 재료, 오염 물질 줄이기)·개인(에너지 아끼기, 대중교통, 일회용품 줄이기, 급식 남기지 않기, 빈 교실 전등 끄기)이 저마다 함 · 누구나 참여할 수 있고 매일 스스로 실천할 일을 골라 실천한 뒤 돌아보고 다시 이어 감',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],8),
('SO5-1-u2-C9','soc',5,1,'u2',5,'인구 분포와 인구 밀도 — 인구는 일정한 지역에 사는 사람의 수, 인구 분포는 그 인구가 모이거나 흩어져 있는 정도 · 인구 분포는 기후·지형 같은 자연환경과 일자리·교통·교육 같은 인문환경의 영향을 받음 · 인구 밀도는 일정한 넓이(1 km²) 안에 사는 사람의 수로 인구가 모여 있는 정도를 알려 줌 — 사람 수와 땅 넓이를 함께 봐야 함(좁은 땅에 많은 사람이면 높음) · 대체로 도시가 발달한 지역에서 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],9),
('SO5-1-u2-C10','soc',5,1,'u2',6,'우리나라 인구 분포의 변화 — 과거(1960년 무렵)에는 벼농사 중심의 농업 사회라 자연환경의 영향을 많이 받아 기후가 온화하고 평야가 발달한 국토의 남서쪽에 모여 살았고, 기온이 낮고 산지가 많은 곳은 인구 밀도가 낮았음 · 1960년대 이후 산업화로 도시가 발달하며 많은 사람이 촌락에서 도시로 옮겨 인구 100명 중 92명 정도가 도시에 살고, 일자리·교통 같은 인문환경의 영향이 커져 수도권(서울특별시·인천광역시·경기도)과 대도시에 모임 — 인구의 절반 정도가 수도권, 옮겨 온 가장 큰 까닭은 직업',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],10),
('SO5-1-u2-C11','soc',5,1,'u2',6,'수도권과 비수도권의 인구 구조 — 인구 구조는 인구를 나이·성별 등으로 나누어 본 짜임새(유소년층 14세 이하·청장년층 15~64세·노년층 65세 이상) · 일자리와 교육 기회를 찾아 청장년층이 모인 수도권은 청장년층 비율이 높고, 청장년층이 빠져나간 비수도권은 노년층 비율이 더 높음',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],11),
('SO5-1-u2-C12','soc',5,1,'u2',7,'인구 분포의 불균형에 따른 문제 — 인구가 집중하는 수도권: 주택 부족과 가격 상승, 교통 혼잡과 주차 문제, 쓰레기와 환경 문제, 시설 부족, 삶의 질 저하 · 인구가 줄어드는 비수도권: 상점·병원·학교 같은 시설과 일자리 감소, 빈집과 폐교, 생활 편의 시설 감소, 청장년층 유출로 일손 부족, 식품 사막 · 두 지역의 일이 서로를 밀어붙이며 되풀이되어 지역 격차가 커지고 국가 경쟁력(다른 나라와 경쟁하는 힘)이 떨어질 수 있음 · 순이동은 들어온 인구수에서 나간 인구수를 뺀 값(20대 청년이 취업과 학업 때문에 수도권으로)',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],12),
('SO5-1-u2-C13','soc',5,1,'u2',8,'인구 분포의 불균형을 해결하는 노력 — 정부: 국가 균형 발전 기구·제도와 법, 공공 기관의 지방 이전(직원과 가족이 함께 옮겨 감)과 혁신 도시(공공 기관 이전을 계기로 새 성장 동력을 만드는 미래형 도시), 고향 사랑 기부제(고향이나 관심 지역에 기부, 답례품과 세금 혜택), 로컬 브랜딩(지역의 자원·문화로 지역만의 매력), 청년 마을 만들기(청년 정착 지원), 디지털 관광 주민증, 작은 학교 살리기 · 지역 스스로: 새 일자리, 주거·교육 환경 개선, 문화생활·창업 지원, 주민이 참여하는 발전 사업(소득 증가 → 지역 경제 활발 → 인구 증가) · 로컬 크리에이터 — 함께 잘 사는 국토',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],13),
('SO5-1-u2-C14','soc',5,1,'u2',8,'해결 방안을 평가하는 세 잣대 — 떠올린 방안은 ① 문제의 원인을 해결하는 데 도움이 되는가 ② 도덕적으로 옳은가(누구에게 억지로 시키거나 벌주지 않는가) ③ 드는 비용과 노력을 생각할 때 실현할 수 있는가를 모두 살핌 — 하나만 보면 좋아 보이던 방안도 다른 잣대에서 걸릴 수 있음 · 방안을 떠올릴 때는 원인을 줄이는 법, 수도권 인구를 나누는 법, 비수도권에 사람이 모이게 하는 법을 생각함',ARRAY['6사 국토 — 우리나라 인구 분포의 특징과 불균형 문제·해결 노력(초안)']::text[],14),
('SO5-1-u2-C15','soc',5,1,'u2',9,'공부한 내용을 동시와 시화로 표현하기 — 단원에서 공부한 내용(기후·자연재해·기후 행동·인구 분포·불균형) 가운데 주제를 고름 → 주제에 대한 내 생각과 경험, 공부한 내용이 드러나게 순서를 생각하며 이야기로 씀 → 하고 싶은 말만 남겨 짧게 줄이고 운율(읽을 때 느껴지는 가락)을 살려 동시로 지음 → 다시 읽으며 이야기 내용이 잘 나타나게 고침 → 동시의 내용을 나타내는 장면을 그려 시화를 완성하고 친구와 바꿔 보며 좋은 점을 말해 줌',ARRAY['6사 국토 — 우리나라 기후의 특징과 기후변화에 따른 자연재해·대응(초안)']::text[],15)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('SO5-1-u2-X01','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'날씨와 기후를 바꾸어 쓴다(하루의 하늘을 기후라고, 여러 해의 모습을 날씨라고 한다)','하루 = 날씨 · 여러 해 = 기후'),
('SO5-1-u2-X02','soc',5,'u2',ARRAY['SO5-1-u2-C1']::text[],'기후를 구성하는 요소(기온·강수·바람)를 놓치거나 지형·인구처럼 대기 상태가 아닌 것을 넣는다','기온 · 강수 · 바람'),
('SO5-1-u2-X03','soc',5,'u2',ARRAY['SO5-1-u2-C2']::text[],'기후와 생활 모습(음식·옷·시설·축제·산업)을 맞지 않게 짝짓거나, 그날의 날씨 때문에 생긴 일을 기후의 영향으로 여긴다','여러 해 되풀이되는 모습에 맞춘 생활'),
('SO5-1-u2-X04','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'계절마다 불어오는 바람의 방향과 성질을 바꾸어 안다(여름에 북서쪽 육지 바람, 겨울에 남쪽 바다 바람 등)','여름 — 남쪽 바다·뜨겁고 습함 · 겨울 — 북서쪽 육지·차갑고 건조'),
('SO5-1-u2-X05','soc',5,'u2',ARRAY['SO5-1-u2-C3']::text[],'남북의 기온 차이를 거꾸로 안다(북쪽이 더 따뜻하다고, 또는 차이가 여름에 더 크다고)','남쪽일수록 따뜻 · 차이는 겨울에 커요'),
('SO5-1-u2-X06','soc',5,'u2',ARRAY['SO5-1-u2-C3','SO5-1-u2-C4']::text[],'등온선·분포도·그래프를 잘못 읽는다(등온선을 강수량이나 높이가 같은 선으로, 진한 색을 적다고 읽는 등)','등온선 = 기온이 같은 곳 · 진할수록 많아요'),
('SO5-1-u2-X07','soc',5,'u2',ARRAY['SO5-1-u2-C4']::text[],'강수의 계절·지역 분포를 거꾸로 안다(겨울에 가장 많다고, 북쪽일수록 많다고)','여름에 절반 이상 · 남쪽으로 갈수록 많아요'),
('SO5-1-u2-X08','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'자연재해의 뜻을 잘못 안다(사람이 일으킨 사고나 피해 없는 자연 현상도 자연재해라고 여긴다)','피할 수 없는 자연 현상 + 사람의 피해'),
('SO5-1-u2-X09','soc',5,'u2',ARRAY['SO5-1-u2-C5']::text[],'계절과 자연재해, 자연재해와 그 특징을 바꾸어 짝짓는다','봄 황사·가뭄 · 여름 폭염·호우·홍수 · 태풍 · 겨울 폭설·한파'),
('SO5-1-u2-X10','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'기상 특보·국민 행동 요령의 뜻을 오해하거나, 행동 요령은 어른만 알면 된다고, 특보가 나와도 평소처럼 지내도 된다고 여긴다','미리 알리는 정보 · 나를 지키는 것도 내 몫'),
('SO5-1-u2-X11','soc',5,'u2',ARRAY['SO5-1-u2-C6']::text[],'사람이 땅의 모습을 바꾸는 일(숲을 일구기·물길 바꾸기)이 자연재해의 피해와 상관없다고 여긴다','숲과 물길은 물을 머금고 흘려보내요'),
('SO5-1-u2-X12','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'기후변화의 원인과 방향을 거꾸로 안다(기온이 내려간다고, 겨울이 길어진다고, 숲 가꾸기가 원인이라고)','인간 활동 → 지구 온난화 → 기온 상승'),
('SO5-1-u2-X13','soc',5,'u2',ARRAY['SO5-1-u2-C7']::text[],'자연재해가 잦고 세진 것을 우연으로 여겨 기후변화와의 관계를 놓친다','더 자주 · 더 세게 · 예측은 더 어렵게'),
('SO5-1-u2-X14','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동의 뜻과 주체를 헷갈린다(관찰·기록으로 여기거나, 특별한 사람이나 나라만 하는 일로, 나 하나 해도 소용없다고 여긴다)','막으려는 모든 노력 · 누구나'),
('SO5-1-u2-X15','soc',5,'u2',ARRAY['SO5-1-u2-C8']::text[],'기후 행동을 고르기만 하고 실천과 돌아보기를 놓치거나, 잘 안 된 날 그만둔다','고르기 → 실천하기 → 돌아보기'),
('SO5-1-u2-X16','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구·인구 분포·인구 밀도의 뜻을 서로 바꾸어 안다','사람 수 · 모인 정도 · 1 km² 안의 사람 수'),
('SO5-1-u2-X17','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 분포에 영향을 주는 환경을 자연환경과 인문환경으로 잘못 나눈다','자연 — 기후·지형 · 인문 — 일자리·교통·교육'),
('SO5-1-u2-X18','soc',5,'u2',ARRAY['SO5-1-u2-C9']::text[],'인구 밀도를 사람 수만으로, 또는 땅 넓이만으로 판단한다(넓은 땅이라서 밀도가 높다고 여기는 등)','사람 수와 넓이를 함께'),
('SO5-1-u2-X19','soc',5,'u2',ARRAY['SO5-1-u2-C10']::text[],'과거와 오늘날의 인구 분포와 그 까닭을 바꾸어 안다(옛날부터 수도권에 모였다고, 사람들이 도시에서 촌락으로 옮겼다고, 오늘날에도 자연환경의 영향이 가장 크다고)','과거 남서쪽 평야·자연 · 오늘 수도권·인문'),
('SO5-1-u2-X20','soc',5,'u2',ARRAY['SO5-1-u2-C10','SO5-1-u2-C11']::text[],'수도권의 범위나 수도권·비수도권의 인구 구조를 잘못 안다','서울·인천·경기 · 수도권은 청장년층이 많아요'),
('SO5-1-u2-X21','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'수도권의 문제와 비수도권의 문제를 바꾸어 짝짓는다(수도권에 빈집·폐교, 비수도권에 집값 상승·교통 혼잡)','몰리는 곳 · 빠져나가는 곳'),
('SO5-1-u2-X22','soc',5,'u2',ARRAY['SO5-1-u2-C12']::text[],'인구 분포의 불균형이 저절로 풀린다고, 한 지역만의 문제라고, 나라 전체의 힘과 관계없다고 여긴다','되풀이되는 두 고리 · 국가 경쟁력'),
('SO5-1-u2-X23','soc',5,'u2',ARRAY['SO5-1-u2-C13']::text[],'불균형을 해결하는 노력의 뜻이나 방향을 헷갈린다(공공 기관을 수도권으로 모은다고, 고향에 사는 사람만 기부한다고 여기는 등)','사람과 일자리가 고르게 · 함께 잘 사는 국토'),
('SO5-1-u2-X24','soc',5,'u2',ARRAY['SO5-1-u2-C14']::text[],'해결 방안을 한 가지 잣대로만 보아, 억지로 옮기게 하거나 벌주는 방안, 비용이 지나친 방안, 원인과 이어지지 않는 방안도 좋다고 여긴다','원인 · 옳음 · 실현 — 셋 다'),
('SO5-1-u2-X25','soc',5,'u2',ARRAY['SO5-1-u2-C2','SO5-1-u2-C4','SO5-1-u2-C10','SO5-1-u2-C12']::text[],'기후와 인구 공부를 통계 수치·연도를 외우는 것으로 여겨 자료에서 특징과 까닭을 읽어 내는 것을 놓친다','외우기보다 자료를 읽고 견주기'),
('SO5-1-u2-X26','soc',5,'u2',ARRAY['SO5-1-u2-C15']::text[],'동시를 지을 때 겪지 않은 일을 넣거나, 이야기를 그대로 옮기거나, 고치지 않거나, 동시와 상관없는 그림을 그린다','내 이야기 · 짧게 · 다시 읽고 고치기 · 내용을 나타내는 그림')
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES 
('g5_1_soc_u2_L01_basic#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"어떤 날은 맑고 어떤 날은 비가 오는 것처럼, 짧은 시간 동안의 대기 상태를 무엇이라고 하나요?","options":[{"t":"날씨","correct":true},{"t":"기후","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"인구","mis":"SO5-1-u2-X02"}],"explanation":["하루 사이에도 바뀌어요.","나가기 전에 확인해요.","이것을 날씨라고 해요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#2','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'mc','auto','오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?',ARRAY['SO5-1-u2-X01','SO5-1-u2-X02']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"mc","stem":"오랜 기간 한 지역에서 나타나는 평균적이며 종합적인 대기 상태는 어느 것인가요?","options":[{"t":"기후","correct":true},{"t":"날씨","mis":"SO5-1-u2-X01"},{"t":"지형","mis":"SO5-1-u2-X02"},{"t":"계절","mis":"SO5-1-u2-X01"}],"explanation":["여러 해를 모아야 보여요.","평균적이고 종합적인 모습이에요.","기후라고 해요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#3','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'sa','auto','공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"sa","stem":"공기의 따뜻하고 차가운 정도를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기온"],"explanation":["덥다·춥다를 나타내요.","온도계로 재요.","기온이에요."],"mis":"SO5-1-u2-X02"}'::jsonb),
('g5_1_soc_u2_L01_basic#4','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',1,'ox','auto','기온·강수·바람은 기후를 구성하는 요소예요.',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C1","difficulty":1,"kind":"ox","stem":"기온·강수·바람은 기후를 구성하는 요소예요.","answer":"O","reason_options":[{"t":"이 셋을 여러 해 동안 살펴보면 그 지역의 대기 상태가 드러나기 때문에","correct":true},{"t":"기후는 땅의 생김새로만 알 수 있기 때문에","mis":"SO5-1-u2-X02"}],"mis":"SO5-1-u2-X02","explanation":["기온은 따뜻하고 차가운 정도예요.","강수는 비·눈, 바람은 공기의 움직임이에요.","셋이 기후를 이뤄요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#5','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"세 친구의 말 가운데 기후를 바르게 말한 친구는 누구인가요?","options":[{"t":"세아","correct":true},{"t":"하람","mis":"SO5-1-u2-X01"},{"t":"도윤","mis":"SO5-1-u2-X01"},{"t":"세 친구 모두","mis":"SO5-1-u2-X01"}],"explanation":["맑은 하늘은 오늘 하루의 일이에요.","매일 바뀌는 것은 날씨예요.","사계절이 뚜렷한 것이 기후예요."],"asset":{"type":"speech","turns":[{"who":"하람","text":"오늘은 하늘이 맑아서 기후가 참 좋네."},{"who":"도윤","text":"어제는 비가 왔으니 기후가 매일 바뀌는 거야."},{"who":"세아","text":"우리나라는 봄·여름·가을·겨울이 뚜렷한 기후야."}]}}'::jsonb),
('g5_1_soc_u2_L01_basic#6','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','기후를 구성하는 요소가 아닌 것은 어느 것인가요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"기후를 구성하는 요소가 아닌 것은 어느 것인가요?","options":[{"t":"지형","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"강수","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"}],"explanation":["기후는 대기의 상태예요.","기온·강수·바람이 요소예요.","지형은 땅의 생김새예요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#7','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',2,'mc','auto','눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?',ARRAY['SO5-1-u2-X02']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"mc","stem":"눈이나 비처럼 하늘에서 땅으로 내린 물을 무엇이라고 하나요?","options":[{"t":"강수","correct":true},{"t":"기온","mis":"SO5-1-u2-X02"},{"t":"바람","mis":"SO5-1-u2-X02"},{"t":"습지","mis":"SO5-1-u2-X02"}],"explanation":["비도 눈도 하늘에서 내려요.","땅에 내린 물이에요.","강수라고 해요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#8','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'mc','auto','기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"mc","stem":"기온이 높고 비가 많이 내리는 지역에서 발달하기 쉬운 음식 문화는 어느 것인가요?","options":[{"t":"벼농사가 활발해 쌀로 만든 음식","correct":true},{"t":"얼음으로만 만든 음식","mis":"SO5-1-u2-X03"},{"t":"물을 거의 쓰지 않는 음식","mis":"SO5-1-u2-X03"},{"t":"바람에 말린 음식만","mis":"SO5-1-u2-X03"}],"explanation":["벼는 물이 많이 필요해요.","덥고 비가 많으면 벼가 잘 자라요.","쌀 음식이 발달했어요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#9','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C2',2,'ox','auto','바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"ox","stem":"바람이 강하게 부는 지역에서는 바람의 힘으로 전기를 만드는 시설이 발달하기 쉬워요.","answer":"O","reason_options":[{"t":"그 지역의 기후를 이용해 산업을 일으키기 때문에","correct":true},{"t":"바람은 기후와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X03"}],"mis":"SO5-1-u2-X03","explanation":["기후는 산업에도 영향을 줘요.","바람이 세면 그 힘을 써요.","바람으로 전기를 만들어요."]}'::jsonb),
('g5_1_soc_u2_L01_basic#10','soc',5,1,'u2','L01','g5_1_soc_u2_L01_basic','lesson_basic','SO5-1-u2-C1',3,'error','auto','날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X01']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C1","difficulty":3,"kind":"error","stem":"날씨와 기후를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"윤서 — 「내일 소풍 가니까 기후를 꼭 확인해야겠어.」","correct":true,"mis_target":"SO5-1-u2-X01"},{"t":"준혁 — 「기후는 여러 해 기록을 모아야 알 수 있어.」","mis":"SO5-1-u2-X01"},{"t":"나린 — 「날씨는 하루 사이에도 바뀌어.」","mis":"SO5-1-u2-X01"}],"explanation":["내일 하루의 대기 상태는 날씨예요.","소풍 전에는 날씨를 봐요.","윤서는 기후라고 잘못 말했어요."]}'::jsonb),
('g5_1_soc_u2_L01_challenge#1','soc',5,1,'u2','L01','g5_1_soc_u2_L01_challenge','lesson_challenge','SO5-1-u2-C1',2,'sa','auto','날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C1","difficulty":2,"kind":"sa","stem":"날씨와 달리 여러 해에 걸쳐 나타나는 평균적이며 종합적인 대기 상태를 두 글자로 무엇이라고 하나요?","answer":["기후"],"explanation":["하루가 아니라 오랜 기간이에요.","평균적인 모습이에요.","기후예요."],"mis":"SO5-1-u2-X01"}'::jsonb),
