('g5_1_soc_u2_L04_basic#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'mc','auto','우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"mc","stem":"우리나라 기후의 변화 자료에서 연평균 기온은 어떻게 달라졌나요?","options":[{"t":"12.0 ℃에서 13.9 ℃로 올라갔다","correct":true},{"t":"13.9 ℃에서 12.0 ℃로 내려갔다","mis":"SO5-1-u2-X12"},{"t":"거의 달라지지 않았다","mis":"SO5-1-u2-X12"},{"t":"여름에만 올라갔다","mis":"SO5-1-u2-X12"}],"explanation":["두 수를 견주어요.","13.9가 더 커요.","기온이 올라갔어요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb),
('g5_1_soc_u2_L04_basic#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"「친환경 재료로 제품을 만들고 생산 과정의 오염 물질을 줄인다」는 누구의 기후 행동인가요?","options":[{"t":"기업","correct":true},{"t":"세계 여러 나라","mis":"SO5-1-u2-X14"},{"t":"정부와 국회","mis":"SO5-1-u2-X14"},{"t":"학교 학생","mis":"SO5-1-u2-X14"}],"explanation":["제품을 만드는 곳이에요.","생산하는 주체예요.","기업의 기후 행동이에요."]}'::jsonb),
('g5_1_soc_u2_L04_basic#8','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',2,'mc','auto','학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X14']::text[],false,'{"seq":8,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"mc","stem":"학교에서 할 수 있는 기후 행동으로 알맞은 것은 어느 것인가요?","options":[{"t":"급식을 남기지 않고 빈 교실과 화장실의 전등을 끈다","correct":true},{"t":"빈 교실의 냉방기를 켜 둔다","mis":"SO5-1-u2-X14"},{"t":"가까운 거리도 자가용을 타고 온다","mis":"SO5-1-u2-X14"},{"t":"일회용 컵을 하루에 여러 개 쓴다","mis":"SO5-1-u2-X14"}],"explanation":["음식과 에너지를 아껴요.","전등을 꺼요.","학교에서도 할 수 있어요."]}'::jsonb),
('g5_1_soc_u2_L04_basic#9','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C7',2,'ox','auto','기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C7","difficulty":2,"kind":"ox","stem":"기후변화의 영향으로 자연재해를 예측하기 어려워지고 그 강도도 세지고 있어요.","answer":"O","reason_options":[{"t":"기후변화로 자연재해의 발생 횟수와 강도가 모두 늘고 있기 때문에","correct":true},{"t":"자연재해는 기후변화와 아무 관계가 없기 때문에","mis":"SO5-1-u2-X13"}],"mis":"SO5-1-u2-X13","explanation":["재해가 더 잦아요.","더 세졌어요.","예측도 어려워요."]}'::jsonb),
('g5_1_soc_u2_L04_basic#10','soc',5,1,'u2','L04','g5_1_soc_u2_L04_basic','lesson_basic','SO5-1-u2-C8',3,'mc','auto','기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":10,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"기후 행동을 실천하고 돌아봤더니 잘 안 된 날이 있었어요. 가장 알맞은 생각은 어느 것인가요?","options":[{"t":"어려웠던 까닭을 생각해 보고 다음에도 이어서 실천한다","correct":true},{"t":"잘 안 된 행동은 목록에서 모두 지운다","mis":"SO5-1-u2-X15"},{"t":"나 하나 해도 달라지지 않으니 그만둔다","mis":"SO5-1-u2-X14"},{"t":"어른이 될 때까지 기후 행동을 미룬다","mis":"SO5-1-u2-X14"}],"explanation":["실천이 어려운 날도 있어요.","까닭을 돌아봐요.","다시 이어 가요."]}'::jsonb),
('g5_1_soc_u2_L04_challenge#1','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'match','auto','기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.','{}'::text[],false,'{"seq":1,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"match","stem":"기후 행동 카드를 보고 카드와 기후 행동을 하는 주체를 알맞게 이으세요.","pairs":[{"l":"㉮","r":"세계 여러 나라"},{"l":"㉯","r":"정부와 국회"},{"l":"㉰","r":"기업"},{"l":"㉱","r":"개인"}],"mis":"SO5-1-u2-X14","explanation":["㉮는 나라들의 약속이에요.","㉯는 법과 제도, ㉰는 제품이에요.","㉱는 내가 매일 할 수 있어요."],"asset":{"type":"passage","lines":["㉮ 기온이 크게 오르지 않도록 함께 약속을 맺었다.","㉯ 기후변화를 막는 법과 제도를 만들었다.","㉰ 친환경 재료로 제품을 만들고 오염 물질을 줄였다.","㉱ 가까운 길은 걷고 휴지 대신 손수건을 쓴다."],"title":"기후 행동 카드 넷"}}'::jsonb),
('g5_1_soc_u2_L04_challenge#2','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',2,'sa','auto','2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)','{}'::text[],false,'{"seq":2,"concept":"SO5-1-u2-C8","difficulty":2,"kind":"sa","stem":"2015년 세계 여러 나라가 기온 상승을 막기로 약속하며 채택한 협정의 이름을 쓰세요. (□□ 협정)","answer":["파리"],"explanation":["여러 나라가 함께 맺었어요.","기온 상승을 막기로 했어요.","파리 협정이에요."],"mis":"SO5-1-u2-X14"}'::jsonb),
('g5_1_soc_u2_L04_challenge#3','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?',ARRAY['SO5-1-u2-X13']::text[],false,'{"seq":3,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"어느 해에 역대 가장 긴 가뭄과 가장 많은 장맛비, 이상 고온과 한파가 한 해에 모두 나타났어요. 가장 알맞은 까닭은 어느 것인가요?","options":[{"t":"기후변화로 자연재해가 더 잦아지고 세졌기 때문에","correct":true},{"t":"그해에만 우연히 생긴 일이기 때문에","mis":"SO5-1-u2-X13"},{"t":"우리나라에 계절이 넷이기 때문에","mis":"SO5-1-u2-X13"},{"t":"자연재해는 원래 미리 다 알 수 있기 때문에","mis":"SO5-1-u2-X13"}],"explanation":["「역대」라는 말이 잦아요.","재해가 더 자주, 더 세게 와요.","기후변화의 영향이에요."]}'::jsonb),
('g5_1_soc_u2_L04_challenge#4','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'mc','auto','기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X14']::text[],false,'{"seq":4,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"mc","stem":"기후변화가 일어나는 과정을 차례대로 바르게 놓은 것은 어느 것인가요?","options":[{"t":"인간 활동 → 지구 온난화 → 기후변화","correct":true},{"t":"기후변화 → 인간 활동 → 지구 온난화","mis":"SO5-1-u2-X12"},{"t":"지구 온난화 → 인간 활동 → 기후변화","mis":"SO5-1-u2-X12"},{"t":"기후 행동 → 지구 온난화 → 인간 활동","mis":"SO5-1-u2-X14"}],"explanation":["사람의 활동이 먼저예요.","그래서 지구가 더워져요.","그 결과 기후가 바뀌어요."]}'::jsonb),
('g5_1_soc_u2_L04_challenge#5','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'mc','auto','「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X15','SO5-1-u2-X14']::text[],false,'{"seq":5,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"mc","stem":"「나의 기후 행동 수첩」에 적기 가장 알맞은 것은 어느 것인가요?","options":[{"t":"휴지 대신 손수건 쓰기","correct":true},{"t":"기후변화를 막는 법 만들기","mis":"SO5-1-u2-X15"},{"t":"생산 과정의 오염 물질 줄이는 기술 개발하기","mis":"SO5-1-u2-X15"},{"t":"에어컨을 세게 틀어 시원하게 지내기","mis":"SO5-1-u2-X14"}],"explanation":["수첩에는 내가 매일 할 일을 적어요.","법은 국회, 기술은 기업의 일이에요.","손수건은 내가 할 수 있어요."]}'::jsonb),
('g5_1_soc_u2_L04_challenge#6','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C8',3,'ox','auto','기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.',ARRAY['SO5-1-u2-X15']::text[],false,'{"seq":6,"concept":"SO5-1-u2-C8","difficulty":3,"kind":"ox","stem":"기후 행동 수첩은 행동을 고르고 적는 데서 끝내고, 실천한 결과는 돌아보지 않아도 돼요.","answer":"X","reason_options":[{"t":"실천한 뒤 돌아보는 일까지 이어져야 생활 속에서 계속할 수 있기 때문에","correct":true},{"t":"기후 행동은 적어 두기만 하면 저절로 이루어지기 때문에","mis":"SO5-1-u2-X15"}],"mis":"SO5-1-u2-X15","explanation":["고르고 실천하고 돌아봐요.","돌아보기까지가 기후 행동이에요.","그래서 X예요."]}'::jsonb),
('g5_1_soc_u2_L04_challenge#7','soc',5,1,'u2','L04','g5_1_soc_u2_L04_challenge','lesson_challenge','SO5-1-u2-C7',3,'error','auto','기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X12','SO5-1-u2-X13']::text[],false,'{"seq":7,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"error","stem":"기후변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하준 — 「기후변화로 우리나라는 겨울이 길어지고 여름이 짧아지고 있어.」","correct":true,"mis_target":"SO5-1-u2-X12"},{"t":"수안 — 「연평균 기온이 꾸준히 올라가고 있어.」","mis":"SO5-1-u2-X12"},{"t":"도경 — 「폭염과 극한 호우가 더 심해지고 있어.」","mis":"SO5-1-u2-X13"}],"explanation":["여름이 길어지고 있어요.","겨울은 짧아지고 있어요.","하준의 말이 거꾸로예요."],"asset":{"type":"passage","lines":["연평균 기온 — 1912~1920년 12.0 ℃ → 2011~2020년 13.9 ℃","여름의 길이 — 98일 → 118일","겨울의 길이 — 109일 → 87일","봄과 가을의 길이 — 크게 달라지지 않았다."],"title":"우리나라 기후의 변화 자료"}}'::jsonb),
