('g5_1_soc_u2_L06_basic#2','soc',5,1,'u2','L06','g5_1_soc_u2_L06_basic','lesson_basic','SO5-1-u2-C10',1,'mc','auto','우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?',ARRAY['SO5-1-u2-X20']::text[],false,'{"seq":2,"concept":"SO5-1-u2-C10","difficulty":1,"kind":"mc","stem":"우리나라의 수도권에 속하는 곳끼리 바르게 묶인 것은 어느 것인가요?","options":[{"t":"서울특별시·인천광역시·경기도","correct":true},{"t":"서울특별시·부산광역시·제주특별자치도","mis":"SO5-1-u2-X20"},{"t":"인천광역시·대구광역시·강원특별자치도","mis":"SO5-1-u2-X20"},{"t":"경기도·전라남도·경상북도","mis":"SO5-1-u2-X20"}],"explanation":["수도를 가운데 두고 이어져요.","서울과 맞닿은 곳이에요.","서울·인천·경기예요."]}'::jsonb),
