('g5_1_soc_u2_review_c#12','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C9',2,'ox','auto','교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.',ARRAY['SO5-1-u2-X17']::text[],false,'{"seq":12,"concept":"SO5-1-u2-C9","difficulty":2,"kind":"ox","stem":"교통이 편리하고 학교가 많은 곳에 사람이 모이는 것은 인문환경의 영향이에요.","answer":"O","reason_options":[{"t":"교통과 교육은 사람이 만든 환경이기 때문에","correct":true},{"t":"교통과 교육은 자연이 만든 환경이기 때문에","mis":"SO5-1-u2-X17"}],"mis":"SO5-1-u2-X17","explanation":["길과 학교는 사람이 만들어요.","그래서 인문환경이에요.","사람이 모여요."]}'::jsonb),
