('g5_1_soc_u2_review_c#18','soc',5,1,'u2','','g5_1_soc_u2_review_c','unit_review','SO5-1-u2-C6',3,'error','auto','자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X11','SO5-1-u2-X08']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C6","difficulty":3,"kind":"error","stem":"자연재해의 피해를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"하람 — 「숲을 없애고 물길을 바꿔도 홍수 피해와는 아무 상관 없어.」","correct":true,"mis_target":"SO5-1-u2-X11"},{"t":"시윤 — 「숲은 빗물을 머금어 피해를 줄여 줘.」","mis":"SO5-1-u2-X11"},{"t":"가윤 — 「자연 현상으로 사람이 피해를 입으면 자연재해야.」","mis":"SO5-1-u2-X08"}],"explanation":["숲과 물길은 물의 흐름을 정해요.","바꾸면 피해가 커지기도 해요.","하람이 잘못 말했어요."]}'::jsonb),
