('g5_1_soc_u2_review_d#9','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C2',2,'error','auto','기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO5-1-u2-X03']::text[],false,'{"seq":9,"concept":"SO5-1-u2-C2","difficulty":2,"kind":"error","stem":"기후가 생활에 주는 영향을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"다빈 — 「오늘 소나기로 소풍이 취소된 건 기후가 생활에 준 영향이야.」","correct":true,"mis_target":"SO5-1-u2-X03"},{"t":"주안 — 「덥고 비가 많은 곳은 벼농사가 활발해.」","mis":"SO5-1-u2-X03"},{"t":"예나 — 「계절마다 입는 옷이 달라져.」","mis":"SO5-1-u2-X03"}],"explanation":["오늘 소나기는 날씨예요.","기후의 영향이 아니에요.","다빈이 잘못 말했어요."]}'::jsonb),
