('g5_1_soc_u2_review_d#17','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C4',3,'ox','auto','연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.',ARRAY['SO5-1-u2-X06']::text[],false,'{"seq":17,"concept":"SO5-1-u2-C4","difficulty":3,"kind":"ox","stem":"연 강수량 분포도에서 남쪽으로 갈수록 파란색이 진해지는 것은 남쪽의 강수량이 더 많다는 뜻이에요.","answer":"O","reason_options":[{"t":"분포도에서 진한 파란색일수록 강수량이 많기 때문에","correct":true},{"t":"진한 파란색일수록 기온이 낮기 때문에","mis":"SO5-1-u2-X06"}],"mis":"SO5-1-u2-X06","explanation":["파란색은 강수량이에요.","진할수록 많아요.","남쪽이 더 많아요."]}'::jsonb),
('g5_1_soc_u2_review_d#18','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C5',3,'ox','auto','다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.',ARRAY['SO5-1-u2-X09']::text[],false,'{"seq":18,"concept":"SO5-1-u2-C5","difficulty":3,"kind":"ox","stem":"다온이 일기 ③의 태풍이 남서쪽에서 올라온 것은 태풍이 대체로 지나가는 길과 맞아요.","answer":"O","reason_options":[{"t":"태풍은 대체로 남서쪽에서 북동쪽으로 지나가기 때문에","correct":true},{"t":"태풍은 언제나 북쪽에서 남쪽으로 내려오기 때문에","mis":"SO5-1-u2-X09"}],"mis":"SO5-1-u2-X09","explanation":["남서쪽에서 올라왔어요.","북동쪽으로 지나가요.","태풍의 길과 맞아요."],"asset":{"type":"passage","lines":["9월 초 — 남서쪽에서 태풍이 올라온다며 태풍 주의보가 내려졌다.","아빠와 베란다의 화분과 빨래 건조대를 안으로 들여놓았다.","그날은 밖에 나가지 않고 집에서 보냈다."],"title":"다온이 일기 ③ 늦여름"}}'::jsonb),
('g5_1_soc_u2_review_d#19','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C7',3,'ox','auto','기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.',ARRAY['SO5-1-u2-X12']::text[],false,'{"seq":19,"concept":"SO5-1-u2-C7","difficulty":3,"kind":"ox","stem":"기후변화는 숲을 파괴하고 석유·석탄을 지나치게 쓰는 인간 활동과 관계가 있어요.","answer":"O","reason_options":[{"t":"이런 인간 활동이 지구 온난화를 심하게 만들기 때문에","correct":true},{"t":"기후변화는 사람과 아무 관계 없이 일어나기 때문에","mis":"SO5-1-u2-X12"}],"mis":"SO5-1-u2-X12","explanation":["사람의 활동이 원인이에요.","지구가 더워져요.","기후가 바뀌어요."]}'::jsonb),
('g5_1_soc_u2_review_d#20','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',3,'ox','auto','오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.',ARRAY['SO5-1-u2-X19']::text[],false,'{"seq":20,"concept":"SO5-1-u2-C10","difficulty":3,"kind":"ox","stem":"오늘날 수도권으로 사람이 모이는 까닭은 주로 기후가 온화하고 평야가 넓기 때문이에요.","answer":"X","reason_options":[{"t":"오늘날에는 일자리·교통 같은 인문환경의 영향이 크기 때문에","correct":true},{"t":"수도권은 우리나라에서 평야가 가장 넓은 곳이기 때문에","mis":"SO5-1-u2-X19"}],"mis":"SO5-1-u2-X19","explanation":["옮겨 온 까닭 1위는 직업이에요.","인문환경의 영향이에요.","그래서 X예요."]}'::jsonb),
('g5_1_soc_u2_review_d#21','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C12',3,'ox','auto','다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.',ARRAY['SO5-1-u2-X21']::text[],false,'{"seq":21,"concept":"SO5-1-u2-C12","difficulty":3,"kind":"ox","stem":"다온이 학교의 운동장 요일제는 학생이 너무 많은 수도권 학교의 모습을 보여 줘요.","answer":"O","reason_options":[{"t":"인구가 몰린 곳은 시설이 부족해 나누어 써야 하기 때문에","correct":true},{"t":"학생이 줄어든 학교라 운동장이 남기 때문에","mis":"SO5-1-u2-X21"}],"mis":"SO5-1-u2-X21","explanation":["학생이 많아요.","운동장이 부족해요.","몰린 곳의 모습이에요."],"asset":{"type":"passage","lines":["우리 동네 한빛시는 경기도에 있는 큰 도시다.","아빠 출근길 지하철은 늘 사람으로 꽉 찬다.","집값이 많이 올라 부모님이 이사를 걱정하신다.","우리 학교는 학생이 많아 학년마다 운동장 쓰는 요일이 정해져 있다."],"title":"다온이 일기 ⑥ 우리 동네"}}'::jsonb),
('g5_1_soc_u2_review_d#22','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C13',3,'ox','auto','솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.',ARRAY['SO5-1-u2-X24']::text[],false,'{"seq":22,"concept":"SO5-1-u2-C13","difficulty":3,"kind":"ox","stem":"솔내 마을의 트럭 상점처럼 물건을 싣고 마을을 찾아가는 방법은 사는 곳에서 주민을 돕는 노력이에요.","answer":"O","reason_options":[{"t":"주민을 이사 보내지 않고 부족한 상점을 채워 주기 때문에","correct":true},{"t":"주민을 도시로 옮겨 살게 하는 방법이기 때문에","mis":"SO5-1-u2-X24"}],"mis":"SO5-1-u2-X24","explanation":["물건이 마을로 가요.","주민은 그대로 살아요.","사는 곳에서 도와요."],"asset":{"type":"passage","lines":["솔내 마을 초등학교에는 올해 1학년 신입생이 한 명도 없다.","마을 가게가 문을 닫아 할머니는 채소를 사기 어려워지셨다.","젊은 사람이 도시로 떠나 농사일을 도울 사람이 부족하다.","요즘은 일주일에 두 번 물건을 실은 트럭 상점이 마을에 온다."],"title":"다온이 일기 ⑦ 할머니 마을"}}'::jsonb),
('g5_1_soc_u2_review_d#23','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C10',4,'mc','auto','다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['SO5-1-u2-X19','SO5-1-u2-X18']::text[],false,'{"seq":23,"concept":"SO5-1-u2-C10","difficulty":4,"kind":"mc","stem":"다온이 일기 ⑦과 ⑧을 함께 볼 때 솔내 마을의 노력이 인구 분포의 변화와 이어지는 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"오늘날 인구 분포는 일자리 같은 인문환경의 영향이 크므로 일거리와 살기 좋은 환경을 만들면 사람을 다시 모을 수 있기 때문에","correct":true},{"t":"오늘날 인구 분포는 기후만 바꾸면 달라지기 때문에","mis":"SO5-1-u2-X19"},{"t":"솔내 마을의 땅을 넓히면 인구 밀도가 높아지기 때문에","mis":"SO5-1-u2-X18"},{"t":"인구 분포는 한 번 정해지면 바뀌지 않기 때문에","mis":"SO5-1-u2-X19"}],"explanation":["사람은 일자리를 찾아 움직여요.","인문환경의 영향이 커요.","일거리가 사람을 불러요."]}'::jsonb),
('g5_1_soc_u2_review_d#24','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C9',4,'essay','teacher','다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO5-1-u2-C9","difficulty":4,"kind":"essay","stem":"다온이 일기 ⑥과 ⑦을 견주어 두 곳의 인구 밀도가 어떻게 다를지 쓰고, 그렇게 된 까닭을 자연환경과 인문환경 가운데 하나와 이어 쓰세요.","answer_guide":{"answer":"예: 한빛시는 지하철이 늘 꽉 차고 학생이 많을 만큼 사람이 몰려 인구 밀도가 높을 것이고, 솔내 마을은 신입생이 없을 만큼 사람이 줄어 인구 밀도가 낮을 것이다. 한빛시에는 일자리와 교통 같은 인문환경이 잘 갖춰져 사람이 모이고, 솔내 마을은 일자리가 적어 젊은 사람이 떠났기 때문이다.","scoring_points":["한빛시의 인구 밀도를 썼는가","솔내 마을의 인구 밀도를 썼는가","환경과 이어 까닭을 썼는가"]},"explanation":["한빛시는 높아요.","솔내 마을은 낮아요.","일자리가 사람을 모아요."]}'::jsonb),
('g5_1_soc_u2_review_d#25','soc',5,1,'u2','','g5_1_soc_u2_review_d','unit_review','SO5-1-u2-C15',4,'essay','teacher','다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO5-1-u2-C15","difficulty":4,"kind":"essay","stem":"다온이처럼 이 단원에서 공부한 내용으로 동시를 짓는다고 생각하고, 주제와 바탕이 될 내 경험을 쓴 뒤 동시 세 줄과 시화에 그릴 장면을 쓰세요.","answer_guide":{"answer":"예: 주제는 자연재해에 대비하는 노력이다. 경험 — 비가 세차게 내린 날 긴급 재난 문자를 보고 높은 길로 돌아왔다. 동시 — 하늘에 구멍 났나 쏟아지는 비 / 주머니에서 울리는 고마운 문자 / 나는 높은 길로 천천히. 장면 — 우산을 쓰고 물이 찬 낮은 길을 피해 높은 길로 걷는 나.","scoring_points":["단원에서 공부한 주제를 골랐는가","내 경험을 썼는가","짧게 줄인 동시 세 줄과 알맞은 장면을 썼는가"]},"explanation":["주제를 골라요.","내 경험이 바탕이에요.","짧게 줄이고 장면을 정해요."],"asset":{"type":"passage","lines":["솔내 마을은 주민이 함께하는 햇빛 발전 사업을 시작해 수익을 나누었다.","도시 청년들이 마을에 머물며 살아 보는 청년 마을도 생겼다.","솔내가 고향인 엄마는 그곳에 고향 사랑 기부를 하고 답례품으로 쌀을 받았다.","나는 이 이야기로 동시를 지어 시화를 만들기로 했다."],"title":"다온이 일기 ⑧ 솔내 마을의 노력"}}'::jsonb)
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES 
('K5-2-u1-C1','kor',5,2,'u1',1,'인상적인 부분의 뜻 — 작품을 읽으며 마음이 움직이거나 궁금증 · 깨달음이 생기는 부분으로, 내 경험이 떠오르는 곳이나 기억에 남는 문장도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],1),
('K5-2-u1-C2','kor',5,2,'u1',1,'사람마다 다른 인상적인 부분 — 같은 작품을 읽어도 마음에 남는 부분은 사람마다 다를 수 있어서, 인상적인 부분에는 하나로 정해진 정답이 없다',ARRAY['6국05-04 문학']::text[],2),
('K5-2-u1-C3','kor',5,2,'u1',1,'부분과 까닭은 한 짝 — 인상적인 부분은 아무 곳이나 고르는 것이 아니라 그 부분이 인상적인 까닭을 작품 속 말이나 내 경험과 이어서 함께 말해야 서로의 생각을 알 수 있다',ARRAY['6국05-04 문학']::text[],3),
('K5-2-u1-C4','kor',5,2,'u1',1,'시와 이야기에서 살필 것 — 시에서는 표현 · 말하는 이의 마음 · 분위기를, 이야기에서는 인물 · 사건 · 때와 곳, 인물의 말과 행동, 사건의 흐름을 살피며 인상적인 부분을 찾는다',ARRAY['6국05-04 문학']::text[],4),
('K5-2-u1-C5','kor',5,2,'u1',1,'단원의 흐름 — 시를 읽고 까닭을 들어 인상적인 부분을 말하고 → 시에 대한 의견을 나누고 → 이야기로 넓힌 뒤 → 서평을 쓰고 → 우리 반 「이달의 책」을 고른다',ARRAY['6국05-04 문학']::text[],5),
('K5-2-u1-C6','kor',5,2,'u1',2,'시를 여러 번 읽고 내용 · 주제 알기 — 시는 여러 번 읽으며 장면을 떠올리고, 무엇을 말하는지(내용)와 말하는 이가 가장 전하고 싶은 생각(주제)을 찾는다',ARRAY['6국05-04 문학']::text[],6),
('K5-2-u1-C7','kor',5,2,'u1',2,'독특하고 재미있는 표현 — 흉내 내는 말 · 빗대어 나타낸 말처럼 독특하고 재미있는 표현은 인상적인 부분이 되기 쉬우며, 그 표현이 어떤 느낌을 주는지까지 말한다',ARRAY['6국05-04 문학']::text[],7),
('K5-2-u1-C8','kor',5,2,'u1',2,'경험과 이어지는 공감 — 시 속 일이 내가 겪은 일과 닮아 「나도 그랬지」 하고 공감되는 부분도 인상적인 부분이며, 그때 떠오른 내 경험이 곧 까닭이 된다',ARRAY['6국05-04 문학']::text[],8),
('K5-2-u1-C9','kor',5,2,'u1',2,'주제가 잘 드러나는 부분 — 말하는 이가 하고 싶은 말이 또렷이 드러나거나 특별한 생각이 들게 하는 부분도 인상적인 부분이며, 제목만으로는 주제를 다 알 수 없어 시 전체를 읽고 찾는다',ARRAY['6국05-04 문학']::text[],9),
('K5-2-u1-C10','kor',5,2,'u1',2,'마음과 분위기도 인상적인 부분 — 인상적인 부분은 한 구절에만 머물지 않아 말하는 이의 마음이나 시 전체의 분위기처럼 시 전체에서 느낀 것도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],10),
('K5-2-u1-C11','kor',5,2,'u1',2,'빗댄 표현을 경험과 이어 읽기 — 「말은 마음에 찍히는 발자국」처럼 빗대어 나타낸 표현은 글자 그대로가 아니라 닮은 점(말이 마음에 남는다)을 찾아, 내 경험이나 배경지식과 이어 이해한다',ARRAY['6국05-04 문학']::text[],11),
('K5-2-u1-C12','kor',5,2,'u1',2,'느낌을 살려 낭송하기 — 인상적인 부분의 느낌이 살도록 빠르기 · 목소리 크기 · 쉬는 곳을 바꾸어 낭송하며, 모두 같은 소리로 크게만 읽는 것이 아니다',ARRAY['6국05-04 문학']::text[],12),
('K5-2-u1-C13','kor',5,2,'u1',4,'공감하며 읽은 시 소개하기 — 수업이나 도서관에서 읽은 시 가운데 공감한 시를 골라 어떤 시인지와 공감한 까닭을 친구에게 소개하며, 꼭 똑같은 일을 겪지 않아도 비슷한 마음을 느껴 보았으면 공감할 수 있다',ARRAY['6국05-04 문학']::text[],13),
('K5-2-u1-C14','kor',5,2,'u1',4,'낱말의 뜻을 알고 읽기 — 모르는 낱말은 앞뒤 문장으로 짐작하고 뜻을 확인하며 읽고(괜스레 — 까닭이나 실속 없이), 낱말을 넣어 문장을 만들어 본다',ARRAY['6국05-04 문학']::text[],14),
('K5-2-u1-C15','kor',5,2,'u1',4,'말하는 이의 마음 흐름 — 시 속 말하는 이의 마음은 처음부터 끝까지 같지 않을 수 있어서(속상함 → 답답함 → 스스로 달래기), 연마다 행동과 말이 어떻게 바뀌는지 따라가며 읽는다',ARRAY['6국05-04 문학']::text[],15),
('K5-2-u1-C16','kor',5,2,'u1',4,'마음 흐름에 맞춘 낭송 — 마음이 바뀌는 곳에서 빠르기와 강약을 바꾸고, 모둠이 연을 나누어 맡아 이어 읽으며 시의 분위기를 살린다',ARRAY['6국05-04 문학']::text[],16),
('K5-2-u1-C17','kor',5,2,'u1',4,'까닭이 다른 까닭 — 친구마다 경험 · 관심사 · 배경지식이 달라 같은 시에서도 인상적인 부분과 그 까닭이 다를 수 있으며, 그렇다고 어느 한쪽이 잘못 읽은 것은 아니다',ARRAY['6국05-04 문학']::text[],17),
('K5-2-u1-C18','kor',5,2,'u1',4,'경청하며 의견 나누기 — 친구의 의견을 끝까지 듣고 나와 같은 점 · 다른 점을 찾으면 미처 생각하지 못한 관점으로 작품을 다시 보게 되어 생각이 넓어진다',ARRAY['6국01-06 듣기·말하기']::text[],18),
('K5-2-u1-C19','kor',5,2,'u1',4,'그림으로 감상 넓히기 — 다른 시를 한 편 더 읽고 인상적인 부분을 그림으로 그린 뒤 그 부분을 고른 까닭을 말하며, 그림은 잘 그렸는지가 아니라 무엇을 왜 골랐는지가 중요하다',ARRAY['6국05-04 문학']::text[],19),
('K5-2-u1-C20','kor',5,2,'u1',7,'전기문의 뜻 — 전기문은 실제로 살았던 인물의 삶을 사실에 근거하여 쓴 글로, 인물이 겪은 일 · 한 일 · 생각을 알려 주어 감동과 교훈을 준다',ARRAY['6국05-04 문학']::text[],20),
('K5-2-u1-C21','kor',5,2,'u1',7,'사실과 다시 꾸민 부분 — 전기문의 사건은 대체로 역사적 사실에 바탕을 두지만 인물이 한 말이나 행동은 작가가 상상하거나 다시 꾸며 표현한 것일 수 있어, 사실과 꾸민 부분을 가려 읽는다',ARRAY['6국05-04 문학']::text[],21),
('K5-2-u1-C22','kor',5,2,'u1',7,'시대적 상황 알기 — 이야기 속 인물이 살았던 때와 곳(나라를 빼앗긴 일제 강점기처럼)을 알아야 인물이 왜 그런 일을 했는지 이해할 수 있다',ARRAY['6국05-04 문학']::text[],22),
('K5-2-u1-C23','kor',5,2,'u1',7,'처한 상황과 말 · 행동 잇기 — 인물이 처한 상황과 그때 한 말이나 행동을 이어 보면 인물의 마음과 생각이 보이며, 말 · 행동만 떼어 보면 그 뜻을 놓친다',ARRAY['6국05-04 문학']::text[],23),
('K5-2-u1-C24','kor',5,2,'u1',7,'이야기에서 인상적인 부분 — 이야기에서는 사건의 흐름 · 인물의 변화 · 기억에 남는 말이나 행동이 인상적인 부분이 되기 쉽고, 이야기의 주제나 분위기도 인상적인 부분이 된다',ARRAY['6국05-04 문학']::text[],24),
('K5-2-u1-C25','kor',5,2,'u1',7,'인상적인 부분으로 질문 만들기 — 인상적인 부분을 중심으로 인물에게 하고 싶은 질문(「그때 무섭지 않았나요?」)을 만들어 친구와 묻고 답하면 인물의 마음에 더 깊이 공감한다',ARRAY['6국05-04 문학']::text[],25),
('K5-2-u1-C26','kor',5,2,'u1',7,'인물의 삶과 나의 삶 — 전기문 속 인물의 삶에서 본받을 점을 찾고 지금 우리의 삶과 이어 보면, 옛사람의 이야기도 오늘의 나에게 뜻이 있음을 알게 된다',ARRAY['6국05-04 문학']::text[],26),
('K5-2-u1-C27','kor',5,2,'u1',10,'서평의 뜻 — 서평은 책을 읽고 그 책에 대한 자신의 의견이나 평가를 까닭과 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],27),
('K5-2-u1-C28','kor',5,2,'u1',10,'서평에 들어갈 내용 — 서평에는 제목 · 책 소개(제목 · 지은이 · 대상 독자 · 주제) · 줄거리 · 인상적인 부분과 그 까닭 · 책에 대한 평가가 들어간다',ARRAY['6국05-04 문학']::text[],28),
('K5-2-u1-C29','kor',5,2,'u1',10,'줄거리는 간단히 — 서평의 줄거리는 일어난 일 가운데 중요한 일만 골라 차례대로 간단히 쓰며, 서평의 중심은 줄거리가 아니라 인상적인 부분과 평가다',ARRAY['6국05-04 문학']::text[],29),
('K5-2-u1-C30','kor',5,2,'u1',10,'평가 — 좋은 점 · 아쉬운 점 · 추천 — 평가에는 좋은 점뿐 아니라 아쉬운 점도 까닭과 함께 쓸 수 있고, 누구에게 왜 추천하는지를 쓴다',ARRAY['6국05-04 문학']::text[],30),
('K5-2-u1-C31','kor',5,2,'u1',10,'독서 감상문과 서평 — 독서 감상문은 책을 읽고 떠오른 생각이나 느낌을 자유롭게 쓴 글이고, 서평은 책의 좋은 점이나 아쉬운 점을 평가하고 그렇게 생각한 까닭을 함께 밝힌 글이다',ARRAY['6국05-04 문학']::text[],31),
('K5-2-u1-C32','kor',5,2,'u1',10,'서평의 제목 붙이기 — 서평의 제목은 책 제목을 그대로 옮기기보다 읽을 사람의 관심을 끌고 책의 핵심 내용이나 내 평가가 드러나게 붙인다',ARRAY['6국05-04 문학']::text[],32),
('K5-2-u1-C33','kor',5,2,'u1',10,'계획하고 쓰고 고쳐 쓰기 — 쓸 내용을 칸마다 정리해 계획하고, 「이 책이 재미있는 까닭은?」처럼 스스로 물으며 쓴 뒤, 친구와 돌려 읽고 받은 의견으로 고쳐 쓴다',ARRAY['6국05-04 문학']::text[],33),
('K5-2-u1-C34','kor',5,2,'u1',12,'추천할 책과 까닭 정리하기 — 「이달의 책」에 어울리는 조건(흥미로운 이야기 · 교훈을 주는 이야기)을 생각해 추천할 책과 추천하는 까닭, 인상적인 부분을 정리하며, 너무 어렵거나 한 분야에만 치우친 책은 피한다',ARRAY['6국05-04 문학']::text[],34),
('K5-2-u1-C35','kor',5,2,'u1',12,'의견 견주기 — 모둠 친구들의 추천 까닭을 끝까지 듣고 같은 점과 다른 점을 견주어 정리한다',ARRAY['6국01-06 듣기·말하기']::text[],35),
('K5-2-u1-C36','kor',5,2,'u1',12,'기준을 세워 조정하기 — 의견이 갈리면 「반 친구들에게 두루 도움이 되는가」처럼 함께 정한 기준에 대어 견주고 조정해 고르며, 목소리 크기나 말한 차례로 정하지 않는다',ARRAY['6국01-06 듣기·말하기']::text[],36),
('K5-2-u1-C37','kor',5,2,'u1',12,'뽑히지 않은 의견도 존중 — 토의는 의견을 견주고 조정하는 과정이어서 뽑히지 않은 책의 추천 까닭도 친구들이 새 책을 알게 하고 다음 후보가 될 수 있으므로, 다양한 의견을 인정한다',ARRAY['6국01-06 듣기·말하기']::text[],37),
('K5-2-u1-C38','kor',5,2,'u1',12,'소개 자료 만들기 — 고른 책은 간단한 소개 · 추천 까닭 · 인상적인 문장을 모아 광고지나 발표 자료로 만들어 반 친구들에게 알린다',ARRAY['6국05-04 문학']::text[],38),
('K5-2-u1-C39','kor',5,2,'u1',14,'인상적인 문장 — 인상적인 문장은 어렵고 긴 문장이 아니라 마음이 움직이거나 깨달음이 생긴 문장이어서, 짧고 쉬운 문장도 내 경험과 이어지면 가장 인상적인 문장이 된다',ARRAY['6국05-04 문학']::text[],39),
('K5-2-u1-C40','kor',5,2,'u1',14,'분류하다 · 분석하다 · 분배하다 — 분류하다(기준에 따라 종류별로 나누거나 묶다) · 분석하다(복잡한 것을 부분으로 나누어 자세히 살피다) · 분배하다(몫으로 나누어 주다)는 모두 「나누다」와 관계있지만 쓰이는 곳이 다르다 (기초 다지기)',ARRAY['기초 다지기(낱말)']::text[],40)
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES 
('K5-2-u1-X01','kor',5,'u1',ARRAY['K5-2-u1-C1']::text[],'인상적인 부분을 글자 수가 많거나 어려운 낱말이 든 부분으로 여긴다','마음이 움직인 곳'),
('K5-2-u1-X02','kor',5,'u1',ARRAY['K5-2-u1-C2']::text[],'작품의 인상적인 부분에는 하나로 정해진 정답이 있다고 여긴다','사람마다 다를 수 있어요'),
('K5-2-u1-X03','kor',5,'u1',ARRAY['K5-2-u1-C3']::text[],'인상적인 부분을 고르고 「그냥 좋아서」처럼 까닭을 말하지 않는다','부분과 까닭은 한 짝'),
('K5-2-u1-X04','kor',5,'u1',ARRAY['K5-2-u1-C3','K5-2-u1-C2']::text[],'정답이 없으니 작품과 이어지지 않는 아무 까닭이나 대도 된다고 여긴다','까닭은 작품과 이어져야'),
('K5-2-u1-X05','kor',5,'u1',ARRAY['K5-2-u1-C4','K5-2-u1-C5']::text[],'시와 이야기에서 살필 것을 헷갈리거나, 단원의 활동 차례를 거꾸로 안다','시 → 이야기 → 서평'),
('K5-2-u1-X06','kor',5,'u1',ARRAY['K5-2-u1-C6']::text[],'시를 한 번 훑어 읽고 내용과 주제를 다 알았다고 여긴다','여러 번 읽어요'),
('K5-2-u1-X07','kor',5,'u1',ARRAY['K5-2-u1-C10']::text[],'인상적인 부분은 멋진 구절 하나뿐이라 여겨, 말하는 이의 마음이나 분위기는 인상적인 부분이 될 수 없다고 본다','시 전체에서 느낀 것도'),
('K5-2-u1-X08','kor',5,'u1',ARRAY['K5-2-u1-C8','K5-2-u1-C13']::text[],'내 경험이 떠올라 고른 부분은 작품과 관계없는 내 이야기라서 까닭이 될 수 없다고 여긴다','「나도 그랬지」도 까닭'),
('K5-2-u1-X09','kor',5,'u1',ARRAY['K5-2-u1-C11','K5-2-u1-C7']::text[],'빗대어 나타낸 표현을 글자 그대로 받아들인다(말이 정말 발자국을 남긴다)','닮은 점을 찾아요'),
('K5-2-u1-X10','kor',5,'u1',ARRAY['K5-2-u1-C12','K5-2-u1-C16']::text[],'낭송은 모든 줄을 같은 빠르기로 크게만 읽으면 된다고 여긴다','느낌 따라 빠르기 · 강약'),
('K5-2-u1-X11','kor',5,'u1',ARRAY['K5-2-u1-C9','K5-2-u1-C6']::text[],'시의 주제는 제목만 보면 다 알 수 있다고 여겨 시 전체를 살피지 않는다','시 전체에서 찾아요'),
('K5-2-u1-X12','kor',5,'u1',ARRAY['K5-2-u1-C13']::text[],'공감은 시와 똑같은 일을 겪어 본 사람만 할 수 있다고 여긴다','비슷한 마음이면 돼요'),
('K5-2-u1-X13','kor',5,'u1',ARRAY['K5-2-u1-C14']::text[],'모르는 낱말을 짐작하거나 확인하지 않고 넘어가 뜻을 잘못 안다(괜스레 → 괜찮게)','앞뒤 문장으로 짐작'),
('K5-2-u1-X14','kor',5,'u1',ARRAY['K5-2-u1-C15']::text[],'말하는 이의 마음은 시의 처음부터 끝까지 같다고 여긴다','연마다 따라가요'),
('K5-2-u1-X15','kor',5,'u1',ARRAY['K5-2-u1-C17']::text[],'친구와 인상적인 부분이 다르면 둘 가운데 한 사람은 잘못 읽은 것이라 여긴다','경험 · 관심사 · 배경지식'),
('K5-2-u1-X16','kor',5,'u1',ARRAY['K5-2-u1-C18','K5-2-u1-C35']::text[],'친구의 의견을 끝까지 듣지 않거나, 나와 다르면 바로 깎아내린다','끝까지 듣고 견줘요'),
('K5-2-u1-X17','kor',5,'u1',ARRAY['K5-2-u1-C19']::text[],'그림으로 감상할 때 잘 그렸는지가 가장 중요하다고 여긴다','무엇을 왜 골랐나'),
('K5-2-u1-X18','kor',5,'u1',ARRAY['K5-2-u1-C20']::text[],'전기문을 지어낸 인물의 이야기로 여기거나, 사실을 담은 글이라 감동은 주지 못한다고 여긴다','실제 인물 · 사실 바탕'),
('K5-2-u1-X19','kor',5,'u1',ARRAY['K5-2-u1-C21']::text[],'전기문 속 인물의 말과 행동은 모두 그날 그대로 받아 적은 것이라 여긴다','다시 꾸몄을 수도'),
('K5-2-u1-X20','kor',5,'u1',ARRAY['K5-2-u1-C22']::text[],'인물이 살았던 시대의 상황을 몰라도 인물이 한 일을 이해할 수 있다고 여긴다','때와 곳을 알아요'),
('K5-2-u1-X21','kor',5,'u1',ARRAY['K5-2-u1-C23']::text[],'인물의 말 · 행동을 처한 상황과 잇지 않고 따로 떼어 본다','상황 + 말 · 행동'),
('K5-2-u1-X22','kor',5,'u1',ARRAY['K5-2-u1-C24']::text[],'이야기에서 인상적인 부분은 가장 큰 사건 한 장면뿐이라 여긴다','흐름 · 변화 · 말 · 분위기'),
('K5-2-u1-X23','kor',5,'u1',ARRAY['K5-2-u1-C25']::text[],'인물에게 하는 질문을 인상적인 부분과 관계없이 글에 답이 그대로 적힌 것만 만든다','인상적인 부분에서 출발'),
('K5-2-u1-X24','kor',5,'u1',ARRAY['K5-2-u1-C26']::text[],'옛날 인물의 이야기는 지금의 나와 아무 관계가 없다고 여긴다','본받을 점 찾기'),
('K5-2-u1-X25','kor',5,'u1',ARRAY['K5-2-u1-C29','K5-2-u1-C28']::text[],'서평은 책의 줄거리를 처음부터 끝까지 자세히 쓰는 글이라 여긴다','줄거리는 간단히'),
('K5-2-u1-X26','kor',5,'u1',ARRAY['K5-2-u1-C30']::text[],'서평에는 책의 좋은 점만 써야 한다고 여긴다','아쉬운 점도 까닭과 함께'),
('K5-2-u1-X27','kor',5,'u1',ARRAY['K5-2-u1-C31','K5-2-u1-C27']::text[],'서평과 독서 감상문을 같은 글로 여긴다','평가와 까닭이 있나?'),
('K5-2-u1-X28','kor',5,'u1',ARRAY['K5-2-u1-C27','K5-2-u1-C30']::text[],'서평의 평가를 「재미있다」처럼 까닭 없이 쓴다','왜 그렇게 평가했나'),
('K5-2-u1-X29','kor',5,'u1',ARRAY['K5-2-u1-C32']::text[],'서평의 제목은 책 제목을 그대로 쓰면 된다고 여긴다','관심 · 핵심이 드러나게'),
('K5-2-u1-X30','kor',5,'u1',ARRAY['K5-2-u1-C33']::text[],'서평을 한 번 쓰면 고쳐 쓸 필요가 없다고 여기거나 친구의 의견을 받지 않는다','돌려 읽고 고쳐 써요'),
('K5-2-u1-X31','kor',5,'u1',ARRAY['K5-2-u1-C34']::text[],'내가 좋아하는 책이면 어렵거나 한 분야에 치우쳐도 반 친구 모두에게 맞는 「이달의 책」이라 여긴다','반 친구들의 눈으로'),
('K5-2-u1-X32','kor',5,'u1',ARRAY['K5-2-u1-C36']::text[],'의견이 갈리면 목소리가 큰 쪽이나 먼저 말한 쪽으로 정한다','함께 정한 기준에 대어요'),
('K5-2-u1-X33','kor',5,'u1',ARRAY['K5-2-u1-C37']::text[],'내가 추천한 책이 뽑히지 않으면 내 의견은 쓸모없었다고 여긴다','견주고 조정하는 과정'),
('K5-2-u1-X34','kor',5,'u1',ARRAY['K5-2-u1-C38']::text[],'소개 자료에는 책 제목만 크게 쓰면 된다고 여긴다','소개 · 까닭 · 문장'),
('K5-2-u1-X35','kor',5,'u1',ARRAY['K5-2-u1-C39']::text[],'인상적인 문장은 길고 어려운 낱말이 많은 문장이어야 한다고 여긴다','짧고 쉬운 문장도'),
('K5-2-u1-X36','kor',5,'u1',ARRAY['K5-2-u1-C40']::text[],'분류하다 · 분석하다 · 분배하다의 뜻을 헷갈려 바꾸어 쓴다','묶기 · 살피기 · 나눠 주기')
